INSERT INTO fieldmaps.form_versions (id, organization_id, project_id, code, definition, form_id, version, state, schema_version, published_at, published_by, created_by, created_at) VALUES ('10000000-0000-4000-8000-000000000104', '10000000-0000-4000-8000-000000000101', '10000000-0000-4000-8000-000000000102', 'training-v1', '{"title": "Janet test subset", "source": "Variables to use for App testing.xlsx, Sheet1 — see docs/Janet-Test-Form-Scope.md", "status": "draft", "summary": "Twelve questions across five acts, drawn from the confirmed candidate subset.", "version": "janet-test-v1", "inclusion": "Excludes all 16 hidden workbook rows (Sheet1 rows 33–40 and 180–187), as the user confirmed for the first test form. Option codes are provisional implementation identifiers and are not workbook values.", "questions": [{"id": "age_range", "act": "Child", "code": "Age1", "hint": "Closest of the six supplied ranges. Observers are not expected to ask.", "kind": "one", "label": "How old is the target child?", "source": "Sheet1 B44:G49", "columns": 3, "options": [{"code": "age_0_2", "label": "0–2 yrs"}, {"code": "age_3_5", "label": "3–5 yrs"}, {"code": "age_6_8", "label": "6–8 yrs"}, {"code": "age_9_12", "label": "9–12 yrs"}, {"code": "age_13_16", "label": "13–16 yrs"}, {"code": "age_17_plus", "label": "17+"}], "required": true, "exportColumn": "Child_AgeRange"}, {"id": "play_type_1", "act": "Play", "code": "PlayType1", "kind": "one", "label": "Primary play type", "source": "Sheet1 B83:G100", "columns": 3, "options": [{"code": "physical", "label": "Physical"}, {"code": "exploratory", "label": "Exploratory"}, {"code": "imaginative", "label": "Imaginative"}, {"code": "play_with_rules", "label": "Play with Rules"}, {"code": "bio", "label": "Bio"}, {"code": "expressive", "label": "Expressive"}, {"code": "restorative", "label": "Restorative"}, {"code": "digital", "label": "Digital"}, {"code": "non_play", "label": "Non-Play"}], "required": true, "exportColumn": "Play_Type_1"}, {"id": "play_subtype_1", "act": "Play", "code": "PlaySubtype1", "kind": "one", "label": "Which kind of play?", "source": "Sheet1 B101:G133", "columns": 2, "options": [], "openedBy": "Subtypes follow the primary play type you chose", "required": false, "dependsOn": {"kind": "answered", "question": "play_type_1"}, "dynamicFrom": {"sets": {"bio": {"code": "Bio_Subtype", "label": "Bio play — which kind?", "options": [{"code": "plants", "label": "Plants"}, {"code": "wildlife", "label": "Wildlife"}, {"code": "care", "label": "Care"}], "exportColumn": "Bio_Subtype"}, "digital": {"code": "Dig_Subtype", "label": "Digital play — which kind?", "options": [{"code": "device", "label": "Device"}, {"code": "augmented", "label": "Augmented"}, {"code": "embedded", "label": "Embedded"}], "exportColumn": "Dig_Subtype"}, "non_play": {"code": "Non_Subtype", "label": "Non-play — which kind?", "options": [{"code": "self_care", "label": "Self care"}, {"code": "nutrition", "label": "Nutrition"}, {"code": "distress", "label": "Distress"}, {"code": "aggression", "label": "Aggression"}, {"code": "transition", "label": "Transition"}, {"code": "other", "label": "Other"}], "exportColumn": "Non_Subtype"}, "physical": {"code": "Phys_Subtype", "label": "Physical play — which kind?", "options": [{"code": "gross_motor", "label": "Gross motor"}, {"code": "fine_motor", "label": "Fine motor"}, {"code": "vestibular", "label": "Vestibular"}, {"code": "rough_and_tumble", "label": "Rough & tumble"}], "exportColumn": "Phys_Subtype"}, "expressive": {"code": "Expr_Subtype", "label": "Expressive play — which kind?", "options": [{"code": "performance", "label": "Performance"}, {"code": "artistic", "label": "Artistic"}, {"code": "language", "label": "Language"}, {"code": "conversation", "label": "Conversation"}], "exportColumn": "Expr_Subtype"}, "exploratory": {"code": "Expl_Subtype", "label": "Exploratory play — which kind?", "options": [{"code": "sensory", "label": "Sensory"}, {"code": "active", "label": "Active"}, {"code": "constructive", "label": "Constructive"}], "exportColumn": "Expl_Subtype"}, "imaginative": {"code": "Imag_Subtype", "label": "Imaginative play — which kind?", "options": [{"code": "symbolic", "label": "Symbolic"}, {"code": "socio_dramatic", "label": "Socio-dramatic"}, {"code": "fantasy", "label": "Fantasy"}], "exportColumn": "Imag_Subtype"}, "restorative": {"code": "Res_Subtype", "label": "Restorative — which kind?", "options": [{"code": "resting", "label": "Resting"}, {"code": "retreat", "label": "Retreat"}, {"code": "reading", "label": "Reading"}, {"code": "onlooking", "label": "Onlooking"}], "exportColumn": "Res_Subtype"}, "play_with_rules": {"code": "PwR_Subtype", "label": "Rules play — which kind?", "options": [{"code": "conventional", "label": "Conventional"}, {"code": "organic", "label": "Organic"}], "exportColumn": "PwR_Subtype"}}, "question": "play_type_1"}, "exportColumn": ""}, {"id": "play_type_2", "act": "Play", "code": "PlayType2", "hint": "Leave it unanswered when a single type describes the event.", "kind": "one", "label": "A second play type, if there is one", "source": "Sheet1 B83:G100", "columns": 3, "options": [{"code": "physical", "label": "Physical"}, {"code": "exploratory", "label": "Exploratory"}, {"code": "imaginative", "label": "Imaginative"}, {"code": "play_with_rules", "label": "Play with Rules"}, {"code": "bio", "label": "Bio"}, {"code": "expressive", "label": "Expressive"}, {"code": "restorative", "label": "Restorative"}, {"code": "digital", "label": "Digital"}, {"code": "non_play", "label": "Non-Play"}], "required": false, "exportColumn": "Play_Type_2", "protocolFlag": "Whether the second slot is required is still a protocol decision. It is optional here and never blocks a save."}, {"id": "play_subtype_2", "act": "Play", "code": "PlaySubtype2", "kind": "one", "label": "Which kind of play?", "source": "Sheet1 B101:G133", "columns": 2, "options": [], "openedBy": "Subtypes follow the second play type you chose", "required": false, "dependsOn": {"kind": "answered", "question": "play_type_2"}, "dynamicFrom": {"sets": {"bio": {"code": "Bio_Subtype", "label": "Bio play — which kind?", "options": [{"code": "plants", "label": "Plants"}, {"code": "wildlife", "label": "Wildlife"}, {"code": "care", "label": "Care"}], "exportColumn": ""}, "digital": {"code": "Dig_Subtype", "label": "Digital play — which kind?", "options": [{"code": "device", "label": "Device"}, {"code": "augmented", "label": "Augmented"}, {"code": "embedded", "label": "Embedded"}], "exportColumn": ""}, "non_play": {"code": "Non_Subtype", "label": "Non-play — which kind?", "options": [{"code": "self_care", "label": "Self care"}, {"code": "nutrition", "label": "Nutrition"}, {"code": "distress", "label": "Distress"}, {"code": "aggression", "label": "Aggression"}, {"code": "transition", "label": "Transition"}, {"code": "other", "label": "Other"}], "exportColumn": ""}, "physical": {"code": "Phys_Subtype", "label": "Physical play — which kind?", "options": [{"code": "gross_motor", "label": "Gross motor"}, {"code": "fine_motor", "label": "Fine motor"}, {"code": "vestibular", "label": "Vestibular"}, {"code": "rough_and_tumble", "label": "Rough & tumble"}], "exportColumn": ""}, "expressive": {"code": "Expr_Subtype", "label": "Expressive play — which kind?", "options": [{"code": "performance", "label": "Performance"}, {"code": "artistic", "label": "Artistic"}, {"code": "language", "label": "Language"}, {"code": "conversation", "label": "Conversation"}], "exportColumn": ""}, "exploratory": {"code": "Expl_Subtype", "label": "Exploratory play — which kind?", "options": [{"code": "sensory", "label": "Sensory"}, {"code": "active", "label": "Active"}, {"code": "constructive", "label": "Constructive"}], "exportColumn": ""}, "imaginative": {"code": "Imag_Subtype", "label": "Imaginative play — which kind?", "options": [{"code": "symbolic", "label": "Symbolic"}, {"code": "socio_dramatic", "label": "Socio-dramatic"}, {"code": "fantasy", "label": "Fantasy"}], "exportColumn": ""}, "restorative": {"code": "Res_Subtype", "label": "Restorative — which kind?", "options": [{"code": "resting", "label": "Resting"}, {"code": "retreat", "label": "Retreat"}, {"code": "reading", "label": "Reading"}, {"code": "onlooking", "label": "Onlooking"}], "exportColumn": ""}, "play_with_rules": {"code": "PwR_Subtype", "label": "Rules play — which kind?", "options": [{"code": "conventional", "label": "Conventional"}, {"code": "organic", "label": "Organic"}], "exportColumn": ""}}, "question": "play_type_2"}, "exportColumn": "", "protocolFlag": "Slot two keeps its own answer and never shares slot one''s values, but the test sheet supplies only one subtype set, so this answer has no export column yet."}, {"id": "cars_intensity", "act": "Play", "code": "CARS2", "hint": "The three supplied CARS bands. Bands are recorded as bands, never as a number.", "kind": "one", "label": "How physically intense is it?", "source": "Sheet1 B135:G137", "columns": 1, "options": [{"code": "cars_1_2", "label": "1–2 · stationary"}, {"code": "cars_3", "label": "3 · slow"}, {"code": "cars_4_5", "label": "4–5 · moderate to vigorous"}], "required": false, "exportColumn": "CARS"}, {"id": "wildlife_interaction", "act": "Setting", "code": "Wildlife1", "kind": "one", "label": "Is the child interacting with wildlife?", "source": "Sheet1 B188:H197", "columns": 2, "options": [{"code": "no", "label": "No"}, {"code": "yes", "label": "Yes"}], "required": false, "exportColumn": "", "protocolFlag": "This branch has no supplied export columns. Answers are stored by question identifier until they are agreed."}, {"id": "wildlife_type", "act": "Setting", "code": "Wildlife2", "kind": "one", "label": "What kind of interaction?", "source": "Sheet1 B188:H197", "columns": 2, "options": [], "openedBy": "Opened by the wildlife answer", "required": false, "dependsOn": {"kind": "equals", "option": "yes", "question": "wildlife_interaction"}, "exportColumn": "", "protocolFlag": "Supply the interaction type list before this version is published. Nothing can be recorded here until then.", "optionsPending": "The workbook does not supply this list. It is left empty rather than filled with examples."}, {"id": "wildlife_other", "act": "Setting", "code": "Wildlife3", "kind": "text", "rows": 2, "label": "Describe the other kind of interaction", "source": "Sheet1 B188:H197", "columns": 1, "options": [], "openedBy": "Opened by the wildlife answer", "required": false, "dependsOn": {"kind": "equals", "option": "yes", "question": "wildlife_interaction"}, "maxLength": 100, "placeholder": "Up to 100 characters", "exportColumn": "", "protocolFlag": "The broad rule reveals this with the whole branch. Confirm whether it should appear only when the interaction type is Other."}, {"id": "wildlife_description", "act": "Setting", "code": "Wildlife4", "kind": "text", "rows": 2, "label": "Describe the wildlife interaction", "source": "Sheet1 B188:H197", "columns": 1, "options": [], "openedBy": "Opened by the wildlife answer", "required": false, "dependsOn": {"kind": "equals", "option": "yes", "question": "wildlife_interaction"}, "maxLength": 100, "placeholder": "Up to 100 characters", "exportColumn": ""}, {"id": "observer_initials", "act": "Record", "code": "Observer1", "hint": "Up to ten uppercase characters. Carried into the next observation in this session.", "kind": "text", "rows": 1, "label": "Who is observing?", "source": "Sheet1 B4:G5", "columns": 1, "options": [], "required": true, "maxLength": 10, "placeholder": "e.g. JL", "exportColumn": "observer"}, {"id": "play_event_summary", "act": "Record", "code": "Summary1", "hint": "A sentence or two, written as you saw it.", "kind": "text", "rows": 4, "label": "Describe the play event", "source": "Sheet1 B42:G42", "columns": 1, "options": [], "required": true, "maxLength": 1000, "placeholder": "Two children dragging a large branch toward the mud kitchen, negotiating who steers…", "exportColumn": "Play_Event_Summary"}], "protocolNotes": [{"id": "presenting-gender", "title": "Presenting gender has no export column", "detail": "Test E51 and Library E75 are both blank. The field is held out of this version until a column name is agreed rather than shipped under an invented one.", "source": "Sheet1 E51 · Library E75"}, {"id": "manufactured-loose-parts", "title": "Manufactured loose parts collide with natural loose parts", "detail": "Test E168 and E169 both read Nat_LP_Intn_Binary, so the two answers would land in one column. The loose-parts group waits for a distinct export name.", "source": "Sheet1 E168 · E169"}, {"id": "natural-materials-list", "title": "The natural materials list has not been provided", "detail": "Test G171 says the list is to be provided. The checklist is held out rather than shipped with the instruction''s own examples standing in as if they were the instrument.", "source": "Sheet1 G171"}, {"id": "play-type-2-required", "title": "Whether a second play type is required is undecided", "detail": "The scope document leaves this open, so the second slot is optional here and never blocks a save.", "source": "Sheet1 B83:G100"}, {"id": "play-subtype-two-slot", "title": "The two-slot subtype interpretation is unconfirmed", "detail": "The test sheet supplies one subtype set. Slot two keeps its own independent answer, but has no export column until the full library''s interpretation is confirmed.", "source": "Sheet1 B101:G133"}, {"id": "wildlife-columns", "title": "The wildlife branch has no supplied export columns or type list", "detail": "Rows B188:H197 name the fields but not their analysis columns, and the interaction type list is not in the sheet. Answers are stored by question identifier only.", "source": "Sheet1 B188:H197"}, {"id": "wildlife-other-reveal", "title": "The wildlife follow-ups use the broad reveal rule", "detail": "All three follow-ups appear on Yes, as the current rule reads. Confirm whether the Other description should appear only when the interaction type is Other.", "source": "Sheet1 H188"}, {"id": "carry-forward", "title": "Which answers carry across observations is undecided", "detail": "This version carries observer initials, zone and round into the next observation and clears every event answer. Round climate and zone inventory are not collected yet.", "source": "Sheet1 G171, G173, G175, G177, G179"}], "knownExportCollisions": []}', '45c54dbd-24a3-4c54-875a-0c5bf7b6673f', 1, 'published', 1, '2026-10-12 14:16:34.744004+00', NULL, NULL, '2026-10-12 14:16:34.741378+00');
