-- Current DECA Mark baseline. Experimental schema history is intentionally replaced.
CREATE EXTENSION IF NOT EXISTS postgis WITH SCHEMA extensions;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='fieldmaps_api') THEN
  CREATE ROLE fieldmaps_api LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS; END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='fieldmaps_sample_reader') THEN CREATE ROLE fieldmaps_sample_reader NOLOGIN; END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='fieldmaps_qgis_training') THEN
  CREATE ROLE fieldmaps_qgis_training LOGIN INHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS; END IF;
END $$;
ALTER ROLE fieldmaps_api SET statement_timeout='15s';
ALTER ROLE fieldmaps_api SET idle_in_transaction_session_timeout='15s';
ALTER ROLE fieldmaps_api SET search_path=pg_catalog;
GRANT fieldmaps_sample_reader TO fieldmaps_qgis_training;
GRANT USAGE ON SCHEMA extensions TO fieldmaps_api,fieldmaps_sample_reader;
ALTER ROLE fieldmaps_qgis_training SET search_path=pg_catalog,extensions,gis;
ALTER ROLE fieldmaps_qgis_training SET statement_timeout='30s';
ALTER ROLE fieldmaps_qgis_training SET idle_in_transaction_session_timeout='30s';
ALTER ROLE fieldmaps_qgis_training SET default_transaction_read_only=on;

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

CREATE SCHEMA fieldmaps;

CREATE SCHEMA fieldmaps_auth_hooks;

CREATE SCHEMA fieldmaps_meta;

CREATE SCHEMA fieldmaps_private;

CREATE SCHEMA gis;

CREATE FUNCTION fieldmaps.advance_observation_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF (NEW.id, NEW.qgis_id, NEW.organization_id, NEW.project_id, NEW.received_at,
      NEW.created_by, NEW.upload_hash)
     IS DISTINCT FROM
     (OLD.id, OLD.qgis_id, OLD.organization_id, OLD.project_id, OLD.received_at,
      OLD.created_by, OLD.upload_hash) THEN
    RAISE EXCEPTION 'Observation identity and receipt cannot change' USING ERRCODE = '23514';
  END IF;
  NEW.revision := OLD.revision + 1;
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps.fill_form_version_lineage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE base text := regexp_replace(NEW.code, '-v[0-9]+$', '');
BEGIN
  IF NEW.form_id IS NULL THEN
    VALUES (NEW.organization_id, NEW.project_id, base, base)
    ON CONFLICT (organization_id, project_id, code) DO NOTHING;
    SELECT id INTO NEW.form_id FROM fieldmaps.forms
    WHERE organization_id = NEW.organization_id AND project_id = NEW.project_id AND code = base;
  END IF;
  NEW.version := coalesce(NEW.version, substring(NEW.code FROM '-v([0-9]+)$')::integer, 1);
  IF NEW.state = 'published' AND NEW.published_at IS NULL THEN
    NEW.published_at := clock_timestamp();
  END IF;
  RETURN NEW;
END;
$_$;

CREATE FUNCTION fieldmaps.latitude(point extensions.geometry) RETURNS double precision
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  SELECT extensions.ST_Y(point);
$$;

CREATE FUNCTION fieldmaps.longitude(point extensions.geometry) RETURNS double precision
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  SELECT extensions.ST_X(point);
$$;

CREATE FUNCTION fieldmaps.make_point(longitude double precision, latitude double precision) RETURNS extensions.geometry
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  SELECT extensions.ST_SetSRID(extensions.ST_MakePoint(longitude, latitude), 4326);
$$;

CREATE FUNCTION fieldmaps.preserve_form_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.state <> 'draft' THEN
      RAISE EXCEPTION 'Published form versions are immutable; publish a new version'
        USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF (NEW.id, NEW.organization_id, NEW.project_id, NEW.code, NEW.form_id, NEW.version,
      NEW.created_by, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.organization_id, OLD.project_id, OLD.code, OLD.form_id, OLD.version,
      OLD.created_by, OLD.created_at) THEN
    RAISE EXCEPTION 'Form version identity cannot change' USING ERRCODE = '23514';
  END IF;
  IF OLD.state = 'draft' AND NEW.state IN ('draft', 'published') THEN
    RETURN NEW;
  END IF;
  IF OLD.state = 'published' AND NEW.state = 'retired'
     AND NEW.definition = OLD.definition AND NEW.schema_version = OLD.schema_version
     AND NEW.published_at IS NOT DISTINCT FROM OLD.published_at
     AND NEW.published_by IS NOT DISTINCT FROM OLD.published_by THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Published form versions are immutable; publish a new version'
    USING ERRCODE = '23514';
END;
$$;

CREATE FUNCTION fieldmaps.preserve_site_package() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  RAISE EXCEPTION 'Prepared packages are immutable; prepare the next version'
    USING ERRCODE = '23514';
END;
$$;

CREATE FUNCTION fieldmaps.protect_organization_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (NEW.id, NEW.is_platform, NEW.plan, NEW.data_region) IS DISTINCT FROM
     (OLD.id, OLD.is_platform, OLD.plan, OLD.data_region) THEN
    RAISE EXCEPTION 'Organization identity cannot change' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps.protect_project_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (NEW.id, NEW.organization_id, NEW.code, NEW.is_training) IS DISTINCT FROM
     (OLD.id, OLD.organization_id, OLD.code, OLD.is_training) THEN
    RAISE EXCEPTION 'Project identity cannot change' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps.request_user_id() RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT nullif(current_setting('fieldmaps.user_id', true), '')::uuid;
$$;

CREATE FUNCTION fieldmaps_auth_hooks.before_user_created(p_event jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  email_domain text := lower(split_part(p_event #>> '{user,email}', '@', -1));
  label_end integer;
BEGIN
  WHILE coalesce(email_domain, '') <> '' LOOP
    IF EXISTS (SELECT FROM fieldmaps_auth_hooks.blocked_email_domains WHERE domain = email_domain) THEN
      RETURN '{"error":{"http_code":400,"message":"Use a permanent email address."}}'::jsonb;
    END IF;
    label_end := strpos(email_domain, '.');
    EXIT WHEN label_end = 0;
    email_domain := substr(email_domain, label_end + 1);
  END LOOP;
  RETURN '{}'::jsonb;
END;
$$;

CREATE FUNCTION fieldmaps_private.assert_active_user() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE caller uuid := fieldmaps.request_user_id();
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('account:' || caller::text, 0));
  IF NOT EXISTS (SELECT FROM auth.users WHERE id = caller)
    OR EXISTS (SELECT FROM fieldmaps.profiles WHERE user_id = caller AND deleted_at IS NOT NULL) THEN
    RAISE EXCEPTION 'account_deleted' USING ERRCODE = 'FM005';
  END IF;
END;
$$;

CREATE FUNCTION fieldmaps_private.assert_zone_observer(p_project uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE org_id uuid;
BEGIN
  PERFORM fieldmaps_private.assert_active_user();
  SELECT organization_id INTO org_id FROM fieldmaps.projects WHERE id = p_project;
  IF org_id IS NULL THEN RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(org_id::text, 0));
  PERFORM fieldmaps_private.assert_active_user();
  IF NOT fieldmaps_private.has_project_role(p_project, ARRAY['observer','manager']) THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;
END;
$$;

CREATE FUNCTION fieldmaps_private.authorize_zone_observation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF current_user <> pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid = TG_RELID)) THEN
    PERFORM fieldmaps_private.assert_zone_observer(NEW.project_id);
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.bind_zone_observation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE package fieldmaps.site_packages; snapshot fieldmaps.package_zones; code text; expected_form uuid;
BEGIN
  IF NEW.package_id IS NULL OR NEW.zone_id IS NULL THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
  SELECT * INTO package FROM fieldmaps.site_packages WHERE id = NEW.package_id
    AND organization_id = NEW.organization_id AND project_id = NEW.project_id AND site_id = NEW.site_id;
  IF NOT FOUND THEN PERFORM fieldmaps_private.reject_zone('package_not_in_site'); END IF;
  IF package.state <> 'ready' OR NOT EXISTS (
    SELECT FROM fieldmaps.zone_publications WHERE published_package_id = package.id) THEN
    PERFORM fieldmaps_private.reject_zone('package_not_ready');
  END IF;
  SELECT * INTO snapshot FROM fieldmaps.package_zones WHERE package_id = package.id AND zone_id = NEW.zone_id;
  IF NOT FOUND THEN PERFORM fieldmaps_private.reject_zone('zone_not_in_package', ARRAY[NEW.zone_id]); END IF;
  SELECT i.code INTO code FROM fieldmaps.zone_identities i WHERE id = snapshot.zone_id;
  NEW.zone_code := code;
  IF NEW.round_type = 'inventory' THEN
    IF NEW.placement_source IS DISTINCT FROM 'zone' OR NEW.first_round IS NOT NULL THEN
      PERFORM fieldmaps_private.reject_zone('invalid_structure', ARRAY[NEW.zone_id]);
    END IF;
    expected_form := package.inventory_form_version_id;
    IF NEW.geom IS NOT NULL THEN PERFORM fieldmaps_private.reject_zone('invalid_structure',ARRAY[NEW.zone_id]); END IF;
  ELSIF NEW.round_type IN ('standard', 'reliability') THEN
    IF NEW.placement_source IS DISTINCT FROM 'hand' OR NEW.first_round IS NULL
      OR NEW.geom IS NULL OR extensions.ST_IsEmpty(NEW.geom) OR extensions.ST_NDims(NEW.geom) <> 2
      OR NOT (extensions.ST_X(NEW.geom) BETWEEN -180 AND 180 AND extensions.ST_Y(NEW.geom) BETWEEN -90 AND 90) THEN
      PERFORM fieldmaps_private.reject_zone('invalid_structure', ARRAY[NEW.zone_id]);
    END IF;
    expected_form := package.form_version_id;
    IF NOT extensions.ST_Covers(snapshot.geom, NEW.geom) THEN
      PERFORM fieldmaps_private.reject_zone('point_outside_zone', ARRAY[NEW.zone_id]);
    END IF;
  ELSE
    PERFORM fieldmaps_private.reject_zone('invalid_structure', ARRAY[NEW.zone_id]);
  END IF;
  IF expected_form IS NULL OR NEW.form_version_id IS DISTINCT FROM expected_form OR NOT EXISTS (
    SELECT FROM fieldmaps.form_versions WHERE id = expected_form AND state IN ('published', 'retired')) THEN
    PERFORM fieldmaps_private.reject_zone('form_not_in_package', ARRAY[NEW.zone_id]);
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.can_read_zone_package(p_package_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (SELECT FROM fieldmaps.site_packages s JOIN fieldmaps.zone_publications p
    ON (p.organization_id, p.project_id, p.site_id, p.published_package_id)
      = (s.organization_id, s.project_id, s.site_id, s.id)
    WHERE s.id = p_package_id AND s.project_id IN (SELECT fieldmaps_private.my_project_ids()));
$$;

CREATE FUNCTION fieldmaps_private.change_org_member(p_org_id uuid, p_user_id uuid, p_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE old_role text;
BEGIN
  PERFORM fieldmaps_private.ensure_profile_row();
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_org_id::text, 0));
  SELECT role INTO old_role FROM fieldmaps.organization_members WHERE organization_id = p_org_id AND user_id = p_user_id;
  IF NOT fieldmaps_private.has_org_role(p_org_id, ARRAY['owner','admin'])
    OR p_role = 'owner'
    OR (NOT fieldmaps_private.has_org_role(p_org_id, ARRAY['owner'])
      AND (old_role <> 'member' OR (p_role IS NOT NULL AND p_role <> 'member'))) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  IF old_role IS NULL THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007'; END IF;
  IF old_role = 'owner' AND (SELECT count(*) FROM fieldmaps.organization_members
    WHERE organization_id = p_org_id AND role = 'owner') = 1 THEN
    RAISE EXCEPTION 'sole_owner' USING ERRCODE = 'FM002';
  END IF;
  IF p_role IS NULL THEN
    IF EXISTS (SELECT FROM fieldmaps.project_memberships m JOIN fieldmaps.projects p ON p.id = m.project_id
      WHERE m.organization_id = p_org_id AND m.user_id = p_user_id AND m.role = 'manager' AND NOT p.is_training
        AND NOT EXISTS (SELECT FROM fieldmaps.project_memberships other
          WHERE other.project_id = m.project_id AND other.user_id <> p_user_id AND other.role = 'manager')) THEN
      RAISE EXCEPTION 'sole_owner' USING ERRCODE = 'FM002';
    END IF;
    DELETE FROM fieldmaps.project_memberships WHERE organization_id = p_org_id AND user_id = p_user_id;
    DELETE FROM fieldmaps.organization_members WHERE organization_id = p_org_id AND user_id = p_user_id;
  ELSE
    UPDATE fieldmaps.organization_members SET role = p_role, granted_by = fieldmaps.request_user_id(), granted_at = now()
    WHERE organization_id = p_org_id AND user_id = p_user_id;
  END IF;
END;
$$;

CREATE FUNCTION fieldmaps_private.change_project_member(p_project_id uuid, p_user_id uuid, p_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE org_id uuid; old_role text; training boolean;
BEGIN
  PERFORM fieldmaps_private.ensure_profile_row();
  SELECT organization_id, is_training INTO org_id, training FROM fieldmaps.projects WHERE id = p_project_id;
  IF org_id IS NULL THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(org_id::text, 0));
  IF NOT fieldmaps_private.has_project_role(p_project_id, ARRAY['manager']) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  SELECT role INTO old_role FROM fieldmaps.project_memberships WHERE project_id = p_project_id AND user_id = p_user_id;
  IF old_role IS NULL THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007'; END IF;
  IF old_role = 'manager' AND p_role IS DISTINCT FROM 'manager' AND NOT training
    AND NOT EXISTS (SELECT FROM fieldmaps.project_memberships
      WHERE project_id = p_project_id AND user_id <> p_user_id AND role = 'manager') THEN
    RAISE EXCEPTION 'sole_owner' USING ERRCODE = 'FM002';
  END IF;
  IF p_role IS NULL THEN
    DELETE FROM fieldmaps.project_memberships WHERE project_id = p_project_id AND user_id = p_user_id;
  ELSE
    UPDATE fieldmaps.project_memberships SET role = p_role, granted_by = fieldmaps.request_user_id(), granted_at = now()
    WHERE project_id = p_project_id AND user_id = p_user_id;
  END IF;
END;
$$;

CREATE FUNCTION fieldmaps_private.valid_zone_draft(p_zones jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
DECLARE
  zone jsonb;
  count_positions integer;
  total_positions integer := 0;
  ids uuid[] := '{}';
  codes text[] := '{}';
  zone_id uuid;
BEGIN
  IF jsonb_typeof(p_zones) <> 'array' OR jsonb_array_length(p_zones) > 250 THEN RETURN false; END IF;
  FOR zone IN SELECT value FROM jsonb_array_elements(p_zones) LOOP
    IF jsonb_typeof(zone) <> 'object'
      OR NOT zone ?& ARRAY['zone_id', 'zone_code', 'zone_label', 'geometry']
      OR (SELECT count(*) FROM jsonb_object_keys(zone)) <> 4
      OR jsonb_typeof(zone -> 'zone_id') <> 'string'
      OR (zone ->> 'zone_id') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
      OR jsonb_typeof(zone -> 'zone_code') <> 'string'
      OR length(zone ->> 'zone_code') NOT BETWEEN 1 AND 100
      OR (zone ->> 'zone_code') COLLATE "C" !~ '^[A-Za-z0-9][A-Za-z0-9_.-]*$'
      OR jsonb_typeof(zone -> 'zone_label') <> 'string'
      OR length(btrim(zone ->> 'zone_label')) NOT BETWEEN 1 AND 200 THEN RETURN false; END IF;
    zone_id := (zone ->> 'zone_id')::uuid;
    IF zone_id = ANY(ids) OR (zone ->> 'zone_code') = ANY(codes) THEN RETURN false; END IF;
    ids := array_append(ids, zone_id);
    codes := array_append(codes, zone ->> 'zone_code');
    count_positions := fieldmaps_private.zone_position_count(zone -> 'geometry');
    IF count_positions IS NULL THEN RETURN false; END IF;
    total_positions := total_positions + count_positions;
    IF total_positions > 20000 THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END;
$_$;

SET default_tablespace = '';

SET default_table_access_method = heap;

CREATE TABLE fieldmaps.zone_drafts (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    site_id uuid NOT NULL,
    base_package_id uuid NOT NULL,
    inventory_form_version_id uuid,
    revision bigint DEFAULT 1 NOT NULL,
    state text DEFAULT 'draft'::text NOT NULL,
    zones jsonb DEFAULT '[]'::jsonb NOT NULL,
    change_note text DEFAULT ''::text NOT NULL,
    create_request_id uuid NOT NULL,
    create_request_hash text NOT NULL,
    create_request jsonb NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    published_package_id uuid,
    site_boundary extensions.geometry(MultiPolygon,4326) NOT NULL,
    CONSTRAINT zone_drafts_change_note_check CHECK ((length(change_note) <= 2000)),
    CONSTRAINT zone_drafts_check CHECK (((state = 'published'::text) = (published_package_id IS NOT NULL))),
    CONSTRAINT zone_drafts_create_request_check CHECK ((jsonb_typeof(create_request) = 'object'::text)),
    CONSTRAINT zone_drafts_create_request_hash_check CHECK ((create_request_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT zone_drafts_revision_check CHECK ((revision > 0)),
    CONSTRAINT zone_drafts_state_check CHECK ((state = ANY (ARRAY['draft'::text, 'published'::text, 'discarded'::text]))),
    CONSTRAINT zone_drafts_zones_check CHECK (fieldmaps_private.valid_zone_draft(zones))
);

CREATE FUNCTION fieldmaps_private.change_zone_draft(p_project uuid, p_site uuid, p_draft uuid, p_revision bigint, p_zones jsonb, p_note text, p_discard boolean DEFAULT false) RETURNS fieldmaps.zone_drafts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result fieldmaps.zone_drafts;
BEGIN
  PERFORM fieldmaps_private.lock_zone_site(p_project, p_site);
  IF p_revision IS NULL OR p_revision < 1 THEN RAISE EXCEPTION 'precondition_required' USING ERRCODE = 'ZB006'; END IF;
  SELECT * INTO result FROM fieldmaps.zone_drafts WHERE id = p_draft AND project_id = p_project
    AND site_id = p_site FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007'; END IF;
  IF result.state = 'published' THEN RAISE EXCEPTION 'conflict' USING ERRCODE = 'FM008'; END IF;
  IF result.revision <> p_revision THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE = 'ZB002'; END IF;
  IF result.state = 'discarded' AND p_discard THEN RETURN result; END IF;
  IF result.state <> 'draft' THEN RAISE EXCEPTION 'conflict' USING ERRCODE = 'FM008'; END IF;
  IF p_discard IS NULL THEN PERFORM fieldmaps_private.reject_zone('invalid_structure'); END IF;
  IF NOT p_discard THEN
    IF p_note IS NULL OR length(fieldmaps_private.zone_trim(p_note)) > 2000 THEN
      PERFORM fieldmaps_private.reject_zone('invalid_structure');
    END IF;
    p_zones := fieldmaps_private.normalize_zone_draft_values(p_zones);
  END IF;
  UPDATE fieldmaps.zone_drafts SET
    zones = CASE WHEN p_discard THEN zones ELSE p_zones END,
    change_note = CASE WHEN p_discard THEN change_note ELSE fieldmaps_private.zone_trim(p_note) END,
    state = CASE WHEN p_discard THEN 'discarded' ELSE 'draft' END,
    revision = revision + 1, updated_at = clock_timestamp(), updated_by = fieldmaps.request_user_id()
    WHERE id = p_draft RETURNING * INTO result;
  RETURN result;
END;
$$;

CREATE FUNCTION fieldmaps_private.create_invitation(p_org_id uuid, p_project_id uuid, p_role text, p_email text, p_max_uses integer, p_expires_in interval, p_token_hash text, p_join_code_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result uuid;
BEGIN
  PERFORM fieldmaps_private.assert_active_user();
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_org_id::text, 0));
  IF p_project_id IS NULL THEN
    IF p_role IS NULL OR p_role NOT IN ('member','admin')
      OR NOT fieldmaps_private.has_org_role(p_org_id, ARRAY['owner','admin'])
      OR (p_role = 'admin' AND NOT fieldmaps_private.has_org_role(p_org_id, ARRAY['owner'])) THEN
      RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
    END IF;
  ELSE
    IF NOT EXISTS (SELECT FROM fieldmaps.projects WHERE id = p_project_id AND organization_id = p_org_id) THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007';
    END IF;
    IF p_role IS NULL OR p_role NOT IN ('observer','viewer','manager')
      OR NOT fieldmaps_private.has_project_role(p_project_id, ARRAY['manager']) THEN
      RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
    END IF;
  END IF;
  IF p_expires_in IS NULL OR p_expires_in <= interval '0 seconds' THEN
    RAISE EXCEPTION 'invitation_invalid' USING ERRCODE = 'FM003';
  END IF;
    expires_at, token_hash, join_code_hash, created_by)
  VALUES (p_org_id, p_project_id, p_role, lower(p_email), p_max_uses,
    now() + p_expires_in, p_token_hash, p_join_code_hash, fieldmaps.request_user_id()) RETURNING id INTO result;
  RETURN result;
END;
$$;

CREATE TABLE fieldmaps.organizations (
    id uuid NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    created_by uuid,
    plan text DEFAULT 'pilot'::text NOT NULL,
    data_region text DEFAULT 'us-east-1'::text NOT NULL,
    is_platform boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT organizations_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT organizations_slug_check CHECK ((slug ~ '^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])$'::text))
);

CREATE FUNCTION fieldmaps_private.create_organization(p_name text, p_slug text, p_project_name text, p_project_code text, p_timezone text) RETURNS fieldmaps.organizations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result fieldmaps.organizations; new_project uuid := gen_random_uuid();
BEGIN
  PERFORM fieldmaps_private.ensure_profile_row();
  IF (SELECT count(*) FROM fieldmaps.organization_members
    WHERE user_id = fieldmaps.request_user_id() AND role = 'owner') >= 3 THEN
    RAISE EXCEPTION 'limit_reached' USING ERRCODE = 'FM001';
  END IF;
  VALUES (gen_random_uuid(), p_name, p_slug, fieldmaps.request_user_id()) RETURNING * INTO result;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(result.id::text, 0));
  VALUES (result.id, fieldmaps.request_user_id(), 'owner', fieldmaps.request_user_id());
  VALUES (new_project, result.id, p_project_name, p_project_code, p_timezone);
  VALUES (fieldmaps.request_user_id(), result.id, new_project, 'manager', fieldmaps.request_user_id());
  RETURN result;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'conflict' USING ERRCODE = 'FM008';
END;
$$;

CREATE TABLE fieldmaps.projects (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    code text NOT NULL,
    description text,
    timezone text DEFAULT 'America/New_York'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    is_training boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT projects_code_check CHECK ((code ~ '^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])$'::text)),
    CONSTRAINT projects_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT projects_status_check CHECK ((status = ANY (ARRAY['active'::text, 'archived'::text])))
);

CREATE FUNCTION fieldmaps_private.create_project(p_org_id uuid, p_name text, p_code text, p_timezone text) RETURNS fieldmaps.projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result fieldmaps.projects;
BEGIN
  PERFORM fieldmaps_private.ensure_profile_row();
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_org_id::text, 0));
  IF NOT fieldmaps_private.has_org_role(p_org_id, ARRAY['owner','admin']) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  VALUES (gen_random_uuid(), p_org_id, p_name, p_code, p_timezone) RETURNING * INTO result;
  VALUES (fieldmaps.request_user_id(), p_org_id, result.id, 'manager', fieldmaps.request_user_id());
  RETURN result;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'conflict' USING ERRCODE = 'FM008';
END;
$$;

CREATE FUNCTION fieldmaps_private.create_zone_draft(p_project uuid,p_site uuid,p_request uuid,p_base uuid)
RETURNS fieldmaps.zone_drafts LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE site fieldmaps.sites; base fieldmaps.site_packages; result fieldmaps.zone_drafts; request jsonb; zones jsonb;
BEGIN
 site:=fieldmaps_private.lock_zone_site(p_project,p_site);
 IF p_request IS NULL OR p_base IS NULL THEN PERFORM fieldmaps_private.reject_zone('invalid_structure'); END IF;
 request:=jsonb_build_object('operation','draft_create','actor',fieldmaps.request_user_id(),
   'project_id',p_project,'site_id',p_site,'base_package_id',p_base);
 SELECT * INTO result FROM fieldmaps.zone_drafts WHERE created_by=fieldmaps.request_user_id()
   AND project_id=p_project AND create_request_id=p_request;
 IF FOUND THEN
   IF result.create_request<>request THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='ZB004'; END IF;
   RETURN result;
 END IF;
 SELECT * INTO base FROM fieldmaps.site_packages WHERE id=p_base AND project_id=p_project AND site_id=p_site;
 IF NOT FOUND THEN PERFORM fieldmaps_private.reject_zone('package_not_in_site'); END IF;
 IF base.state<>'ready' OR NOT fieldmaps_private.can_read_zone_package(base.id) THEN
   PERFORM fieldmaps_private.reject_zone('package_not_ready'); END IF;
 SELECT jsonb_agg(jsonb_build_object('zone_id',z.zone_id,'zone_code',i.code,'zone_label',z.label,
   'geometry',z.canonical_geometry) ORDER BY i.code COLLATE "C") INTO zones
 FROM fieldmaps.package_zones z JOIN fieldmaps.zone_identities i ON i.id=z.zone_id WHERE z.package_id=base.id;
 zones:=fieldmaps_private.normalize_zone_draft_values(zones);
   zones,create_request_id,create_request_hash,create_request,created_by,updated_by,site_boundary)
 VALUES(gen_random_uuid(),site.organization_id,p_project,p_site,p_base,base.inventory_form_version_id,zones,p_request,
   encode(sha256(convert_to(request::text,'UTF8')),'hex'),request,fieldmaps.request_user_id(),fieldmaps.request_user_id(),base.site_boundary)
 RETURNING * INTO result;
 RETURN result;
END;
$$;

CREATE TABLE fieldmaps.profiles (
    user_id uuid NOT NULL,
    display_name text,
    observer_initials text,
    locale text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT profiles_display_name_check CHECK (((length(btrim(display_name)) >= 1) AND (length(btrim(display_name)) <= 100))),
    CONSTRAINT profiles_observer_initials_check CHECK ((observer_initials ~ '^[A-Z0-9]{1,10}$'::text))
);

CREATE FUNCTION fieldmaps_private.ensure_profile(p_display_name text) RETURNS fieldmaps.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result fieldmaps.profiles;
BEGIN
  PERFORM fieldmaps_private.ensure_profile_row();
  UPDATE fieldmaps.profiles SET display_name = p_display_name
  WHERE user_id = fieldmaps.request_user_id() AND display_name IS NULL AND p_display_name IS NOT NULL;
  SELECT * INTO result FROM fieldmaps.profiles WHERE user_id = fieldmaps.request_user_id();
  RETURN result;
END;
$$;

CREATE FUNCTION fieldmaps_private.ensure_profile_row() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE training_org uuid;
BEGIN
  PERFORM fieldmaps_private.assert_active_user();
  SELECT organization_id INTO training_org FROM fieldmaps.projects
  WHERE id = '10000000-0000-4000-8000-000000000102';
  IF training_org IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(training_org::text, 0));
    SELECT fieldmaps.request_user_id(), organization_id, id, 'observer' FROM fieldmaps.projects
    WHERE id = '10000000-0000-4000-8000-000000000102' ON CONFLICT DO NOTHING;
  END IF;
END;
$$;

CREATE TABLE fieldmaps.site_packages (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    site_id uuid NOT NULL,
    form_version_id uuid NOT NULL,
    version integer NOT NULL,
    state text NOT NULL,
    manifest jsonb NOT NULL,
    archive bytea NOT NULL,
    archive_sha256 text NOT NULL,
    prepared_by uuid NOT NULL,
    prepared_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    site_boundary extensions.geometry(MultiPolygon,4326) NOT NULL,
    inventory_form_version_id uuid,
    CONSTRAINT site_packages_archive_check CHECK (((octet_length(archive) >= 1) AND (octet_length(archive) <= 16777216))),
    CONSTRAINT site_packages_archive_sha256_check CHECK ((archive_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT site_packages_manifest_check CHECK ((jsonb_typeof(manifest) = 'object'::text)),
    CONSTRAINT site_packages_state_check CHECK ((state = ANY (ARRAY['ready'::text, 'blocked'::text]))),
    CONSTRAINT site_packages_version_check CHECK ((version > 0))
);

CREATE FUNCTION fieldmaps_private.finalize_zone_package(p_project uuid, p_site uuid, p_request uuid, p_expected_current uuid, p_draft uuid, p_revision bigint, p_package uuid, p_version integer, p_manifest jsonb, p_zone_layer jsonb, p_archive bytea, p_checks jsonb, p_import_body jsonb DEFAULT NULL::jsonb, p_zone_layer_bytes bytea DEFAULT NULL::bytea) RETURNS TABLE(package fieldmaps.site_packages, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET extra_float_digits TO '3'
    AS $_$
DECLARE
  site fieldmaps.sites; draft fieldmaps.zone_drafts; base fieldmaps.site_packages; event fieldmaps.zone_publications;
  result fieldmaps.site_packages; request jsonb; publication_operation text; current_package uuid; next_version integer;
  validation jsonb; zones jsonb; note text; ground extensions.geometry; imported jsonb;
  zone jsonb; shape extensions.geometry; anchor extensions.geometry; identity_map jsonb;
  expected_zones jsonb := '[]'; expected_features jsonb := '[]'; extent extensions.box3d;
  forms jsonb; play uuid; inventory uuid; play_code text; inventory_code text;
BEGIN
  site := fieldmaps_private.lock_zone_site(p_project, p_site);
  IF p_request IS NULL OR (p_draft IS NOT NULL AND (p_revision IS NULL OR p_expected_current IS NULL)) THEN
    RAISE EXCEPTION 'precondition_required' USING ERRCODE = 'ZB006';
  END IF;
  IF p_draft IS NULL AND NOT coalesce(p_import_body ? 'expected_current_package_id',false) THEN
    RAISE EXCEPTION 'precondition_required' USING ERRCODE='ZB006'; END IF;
  publication_operation := CASE WHEN p_draft IS NULL THEN 'package_import' ELSE 'draft_publish' END;
  IF (p_draft IS NULL) <> (p_import_body IS NOT NULL) THEN PERFORM fieldmaps_private.reject_zone('invalid_structure'); END IF;
  request := jsonb_build_object('operation', publication_operation, 'actor', fieldmaps.request_user_id(),
    'project_id', p_project, 'site_id', p_site, 'draft_id', p_draft, 'revision', p_revision,
    'expected_current_package_id', p_expected_current, 'body', CASE WHEN p_draft IS NULL THEN p_import_body
      ELSE jsonb_build_object('request_id', p_request, 'expected_current_package_id', p_expected_current) END);
  SELECT * INTO event FROM fieldmaps.zone_publications WHERE created_by = fieldmaps.request_user_id()
    AND project_id = p_project AND zone_publications.operation = publication_operation AND request_id = p_request;
  IF FOUND THEN
    IF event.request <> request THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE = 'ZB004'; END IF;
    SELECT * INTO result FROM fieldmaps.site_packages WHERE id = event.published_package_id;
    RETURN QUERY SELECT result, true;
    RETURN;
  END IF;
  current_package := fieldmaps_private.zone_current_package(p_site);
  IF current_package IS DISTINCT FROM p_expected_current THEN
    RAISE EXCEPTION 'publication_conflict' USING ERRCODE = 'ZB003', DETAIL =
      jsonb_build_object('current_package_id', current_package)::text;
  END IF;
  SELECT * INTO base FROM fieldmaps.site_packages WHERE id = current_package AND project_id = p_project AND site_id = p_site;
  IF current_package IS NOT NULL AND (NOT FOUND OR base.state <> 'ready') THEN PERFORM fieldmaps_private.reject_zone('package_not_ready'); END IF;
  IF p_draft IS NOT NULL THEN
    SELECT * INTO draft FROM fieldmaps.zone_drafts WHERE id = p_draft AND project_id = p_project AND site_id = p_site FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007'; END IF;
    IF draft.revision <> p_revision THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE = 'ZB002'; END IF;
    IF draft.state <> 'draft' THEN RAISE EXCEPTION 'conflict' USING ERRCODE = 'FM008'; END IF;
    IF draft.base_package_id <> current_package THEN RAISE EXCEPTION 'publication_conflict' USING ERRCODE = 'ZB003'; END IF;
    zones := draft.zones; ground := draft.site_boundary; play := base.form_version_id; inventory := draft.inventory_form_version_id; note := draft.change_note;
    SELECT jsonb_agg(jsonb_build_object('zone_id', value -> 'zone_id', 'zone_code', value -> 'zone_code') ORDER BY ordinal)
      INTO identity_map FROM jsonb_array_elements(zones) WITH ORDINALITY z(value, ordinal);
  ELSE
      IF p_import_body ->> 'request_id' IS DISTINCT FROM p_request::text
      OR p_import_body ->> 'expected_current_package_id' IS DISTINCT FROM p_expected_current::text
      OR p_import_body ->> 'site_id' IS DISTINCT FROM p_site::text THEN
      PERFORM fieldmaps_private.reject_zone('invalid_structure');
    END IF;
    imported := fieldmaps_private.zone_import_input(p_import_body);
    zones := fieldmaps_private.normalize_zone_draft_values(imported -> 'zones');
    note := p_import_body ->> 'change_note';
    forms := fieldmaps_private.zone_import_forms(p_project, base.id, p_import_body);
    play := (forms #>> '{play,form_version_id}')::uuid;
    inventory := (forms #>> '{inventory,form_version_id}')::uuid;
    ground := extensions.ST_GeomFromGeoJSON(fieldmaps_private.normalize_zone_geometry(imported -> 'ground', 2147483647));
    identity_map := p_import_body -> 'zone_identity_map';
  END IF;
  IF note IS NULL OR length(fieldmaps_private.zone_trim(note)) > 2000 THEN PERFORM fieldmaps_private.reject_zone('invalid_structure'); END IF;
  note := fieldmaps_private.zone_trim(note);
  PERFORM 1 FROM fieldmaps.form_versions WHERE id IN (play, inventory) ORDER BY id FOR SHARE;
  SELECT code INTO play_code FROM fieldmaps.form_versions WHERE id = play;
  SELECT code INTO inventory_code FROM fieldmaps.form_versions WHERE id = inventory;
  validation := fieldmaps_private.zone_validation(p_project, p_site, zones, ground, play, inventory, note);
  IF validation -> 'ready' <> 'true'::jsonb THEN
    RAISE EXCEPTION 'validation_failed' USING ERRCODE = 'ZB001', DETAIL = jsonb_build_object('issues', validation -> 'issues')::text;
  END IF;
  SELECT coalesce(max(version), 0) + 1 INTO next_version FROM fieldmaps.site_packages WHERE site_id = p_site;
  IF p_version IS DISTINCT FROM next_version THEN RAISE EXCEPTION 'publication_conflict' USING ERRCODE = 'ZB003'; END IF;
  IF p_package IS NULL THEN PERFORM fieldmaps_private.reject_zone('invalid_structure'); END IF;
  forms := jsonb_build_object('play', jsonb_build_object('form_version_id', play, 'form_version', play_code),
    'inventory', CASE WHEN inventory IS NULL THEN NULL ELSE jsonb_build_object('form_version_id', inventory, 'form_version', inventory_code) END);
  FOR zone IN SELECT jsonb_array_elements(validation -> 'canonical_zones') LOOP
    shape := extensions.ST_GeomFromGeoJSON(zone -> 'geometry'); extent := shape::extensions.box3d;
    expected_zones := expected_zones || jsonb_build_array(jsonb_build_object('label', zone -> 'zone_label',
      'bbox', jsonb_build_array(extensions.ST_XMin(extent),extensions.ST_YMin(extent),extensions.ST_XMax(extent),extensions.ST_YMax(extent)),
      'zone_id', zone -> 'zone_id', 'zone_code', zone -> 'zone_code',
      'display_anchor', zone -> 'display_anchor', 'geometry_sha256', zone -> 'geometry_sha256'));
    expected_features := expected_features || jsonb_build_array(jsonb_build_object('type', 'Feature', 'geometry', zone -> 'geometry',
      'properties', jsonb_build_object('zone_id', zone -> 'zone_id', 'zone_code', zone -> 'zone_code',
        'name', zone -> 'zone_label', 'display_anchor', zone -> 'display_anchor', 'geometry_sha256', zone -> 'geometry_sha256')));
  END LOOP;
  IF p_manifest IS NULL OR p_manifest -> 'format' IS DISTINCT FROM '1'::jsonb
    OR (SELECT count(*) FROM jsonb_object_keys(p_manifest)) <> 7
    OR p_manifest ->> 'site_id' IS DISTINCT FROM p_site::text OR p_manifest ->> 'site_code' IS DISTINCT FROM site.code
    OR p_manifest ->> 'package_id' IS DISTINCT FROM p_package::text
    OR p_manifest -> 'package_version' IS DISTINCT FROM to_jsonb(next_version)
    OR p_manifest -> 'forms' IS DISTINCT FROM forms
    OR p_manifest -> 'zones' IS DISTINCT FROM expected_zones
    OR p_zone_layer IS DISTINCT FROM jsonb_build_object('type', 'FeatureCollection', 'features', expected_features) THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
  IF p_checks IS NULL OR jsonb_typeof(p_checks) <> 'array' OR jsonb_array_length(p_checks) NOT BETWEEN 1 AND 5
    OR EXISTS (SELECT FROM jsonb_array_elements(p_checks) WHERE value ->> 'state' IS NULL
      OR value ->> 'state' NOT IN ('passed', 'warning', 'skipped')) THEN
    PERFORM fieldmaps_private.reject_zone('package_not_ready');
  END IF;
  IF p_zone_layer_bytes IS NULL THEN PERFORM fieldmaps_private.reject_zone('invalid_structure'); END IF;
  BEGIN
    IF convert_from(p_zone_layer_bytes, 'UTF8')::jsonb IS DISTINCT FROM p_zone_layer THEN
      PERFORM fieldmaps_private.reject_zone('invalid_structure');
    END IF;
  EXCEPTION WHEN character_not_in_repertoire OR invalid_text_representation THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END;
    manifest, archive, archive_sha256, prepared_by, site_boundary, inventory_form_version_id)
  VALUES (p_package, site.organization_id, p_project, p_site, play, next_version, 'ready', p_manifest, p_archive,
    encode(sha256(p_archive), 'hex'), fieldmaps.request_user_id(), ground, inventory) RETURNING * INTO result;
    SELECT p_package, ordinal - 1, value ->> 'step', value ->> 'state', value ->> 'detail'
    FROM jsonb_array_elements(p_checks) WITH ORDINALITY c(value, ordinal);
  FOR zone IN SELECT jsonb_array_elements(validation -> 'canonical_zones') LOOP
    VALUES ((zone ->> 'zone_id')::uuid, site.organization_id, p_project, p_site, zone ->> 'zone_code', fieldmaps.request_user_id())
    ON CONFLICT (id) DO NOTHING;
    IF NOT EXISTS (SELECT FROM fieldmaps.zone_identities WHERE id = (zone ->> 'zone_id')::uuid
      AND project_id = p_project AND site_id = p_site AND code = zone ->> 'zone_code') THEN
      PERFORM fieldmaps_private.reject_zone('identity_conflict', ARRAY[(zone ->> 'zone_id')::uuid]);
    END IF;
    shape := extensions.ST_GeomFromGeoJSON(zone -> 'geometry');
    anchor := extensions.ST_SetSRID(extensions.ST_MakePoint((zone #>> '{display_anchor,0}')::double precision,
      (zone #>> '{display_anchor,1}')::double precision), 4326);
      label, geom, display_anchor, geometry_sha256, canonical_geometry)
    VALUES (site.organization_id, p_project, p_site, p_package, (zone ->> 'zone_id')::uuid,
      zone ->> 'zone_label', shape, anchor, zone ->> 'geometry_sha256', zone -> 'geometry');
  END LOOP;
  IF (SELECT count(*) FROM fieldmaps.package_zones WHERE package_id = p_package) <> jsonb_array_length(expected_zones) THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
    draft_id, draft_revision, expected_current_package_id, request_hash, request, published_package_id, identity_map, change_note)
  VALUES (p_request, fieldmaps.request_user_id(), site.organization_id, p_project, p_site, publication_operation, p_draft, p_revision,
    p_expected_current, encode(sha256(convert_to(request::text, 'UTF8')), 'hex'), request, p_package, identity_map, note);
  IF EXISTS (SELECT FROM fieldmaps.site_zone_state WHERE site_id = p_site) THEN
    UPDATE fieldmaps.site_zone_state SET current_package_id = p_package, revision = next_version WHERE site_id = p_site;
  ELSE
    VALUES (p_site, site.organization_id, p_project, p_package, next_version);
  END IF;
  IF p_draft IS NOT NULL THEN
    UPDATE fieldmaps.zone_drafts SET state = 'published', revision = revision + 1, published_package_id = p_package,
      updated_at = clock_timestamp(), updated_by = fieldmaps.request_user_id() WHERE id = p_draft;
  END IF;
  RETURN QUERY SELECT result, false;
END;
$_$;

CREATE FUNCTION fieldmaps_private.forget_user() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE caller uuid := fieldmaps.request_user_id(); org_id uuid; training_org uuid;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('account:' || caller::text, 0));
  IF NOT EXISTS (SELECT FROM auth.users WHERE id = caller) THEN RETURN; END IF;
  IF EXISTS (SELECT FROM fieldmaps.profiles WHERE user_id = caller AND deleted_at IS NOT NULL) THEN RETURN; END IF;
  SELECT organization_id INTO training_org FROM fieldmaps.projects WHERE id = '10000000-0000-4000-8000-000000000102';
  IF training_org IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(training_org::text, 0));
  END IF;
  FOR org_id IN SELECT organization_id FROM fieldmaps.organization_members WHERE user_id = caller
    UNION SELECT organization_id FROM fieldmaps.project_memberships WHERE user_id = caller ORDER BY 1 LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(org_id::text, 0));
  END LOOP;
  IF EXISTS (SELECT FROM fieldmaps.organization_members m WHERE m.user_id = caller AND m.role = 'owner'
    AND EXISTS (SELECT FROM fieldmaps.organization_members other WHERE other.organization_id = m.organization_id AND other.user_id <> caller)
    AND NOT EXISTS (SELECT FROM fieldmaps.organization_members other WHERE other.organization_id = m.organization_id AND other.user_id <> caller AND other.role = 'owner')) THEN
    RAISE EXCEPTION 'sole_owner' USING ERRCODE = 'FM002';
  END IF;
  UPDATE fieldmaps.organizations o SET deleted_at = now()
  WHERE EXISTS (SELECT FROM fieldmaps.organization_members m WHERE m.organization_id = o.id AND m.user_id = caller AND m.role = 'owner')
    AND NOT EXISTS (SELECT FROM fieldmaps.organization_members m WHERE m.organization_id = o.id AND m.user_id <> caller);
  IF EXISTS (SELECT FROM fieldmaps.project_memberships m
    JOIN fieldmaps.projects p ON p.id = m.project_id
    JOIN fieldmaps.organizations o ON o.id = m.organization_id
    WHERE m.user_id = caller AND m.role = 'manager' AND NOT p.is_training AND o.deleted_at IS NULL
      AND NOT EXISTS (SELECT FROM fieldmaps.project_memberships other
        WHERE other.project_id = m.project_id AND other.user_id <> caller AND other.role = 'manager')) THEN
    RAISE EXCEPTION 'sole_owner' USING ERRCODE = 'FM002';
  END IF;
  DELETE FROM fieldmaps.project_memberships WHERE user_id = caller;
  DELETE FROM fieldmaps.organization_members WHERE user_id = caller;
  ON CONFLICT (user_id) DO UPDATE SET display_name = NULL, observer_initials = NULL, locale = NULL,
    deleted_at = coalesce(fieldmaps.profiles.deleted_at, now());
END;
$$;

CREATE FUNCTION fieldmaps_private.guard_current_zone_form_retirement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.state='published' AND NEW.state='retired' AND EXISTS (
    SELECT FROM fieldmaps.site_zone_state st JOIN fieldmaps.site_packages k ON k.id=st.current_package_id
    WHERE k.form_version_id=OLD.id OR k.inventory_form_version_id=OLD.id) THEN
    RAISE EXCEPTION 'current_package_form' USING ERRCODE='ZB007';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.guard_package_zone_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT FROM fieldmaps.zone_publications p
    WHERE (p.organization_id, p.project_id, p.site_id, p.published_package_id)
      = (NEW.organization_id, NEW.project_id, NEW.site_id, NEW.package_id)) THEN
    RAISE EXCEPTION 'Published zone snapshots cannot be appended' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT FROM fieldmaps.site_packages p
    WHERE (p.organization_id, p.project_id, p.site_id, p.id)
      = (NEW.organization_id, NEW.project_id, NEW.site_id, NEW.package_id)
      AND p.state = 'ready') THEN
    RAISE EXCEPTION 'Zone snapshots require a ready managed package' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.guard_site_zone_state() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE target fieldmaps.site_packages;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain site history' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ((NEW.site_id,NEW.organization_id,NEW.project_id,NEW.enabled_at)
    IS DISTINCT FROM (OLD.site_id,OLD.organization_id,OLD.project_id,OLD.enabled_at) OR NEW.revision<=OLD.revision) THEN
   RAISE EXCEPTION 'Publish a newer site version' USING ERRCODE='23514'; END IF;
 SELECT * INTO target FROM fieldmaps.site_packages WHERE (organization_id,project_id,site_id,id)
   =(NEW.organization_id,NEW.project_id,NEW.site_id,NEW.current_package_id);
 IF NOT FOUND OR target.state<>'ready' OR NEW.revision<>target.version
   OR NOT EXISTS(SELECT FROM fieldmaps.package_zones WHERE package_id=target.id) THEN
   RAISE EXCEPTION 'Current selection requires a ready snapshot and its package version' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.guard_zone_draft_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.state <> 'draft' THEN
    RAISE EXCEPTION 'Retain zone drafts and immutable published results' USING ERRCODE = '23514';
  END IF;
  IF (NEW.id, NEW.organization_id, NEW.project_id, NEW.site_id, NEW.base_package_id,
      NEW.inventory_form_version_id, NEW.create_request_id, NEW.create_request_hash,
      NEW.create_request, NEW.created_by, NEW.created_at)
    IS DISTINCT FROM (OLD.id, OLD.organization_id, OLD.project_id, OLD.site_id, OLD.base_package_id,
      OLD.inventory_form_version_id, OLD.create_request_id, OLD.create_request_hash,
      OLD.create_request, OLD.created_by, OLD.created_at) OR NEW.revision <> OLD.revision + 1 THEN
    RAISE EXCEPTION 'Draft lineage is immutable and revision must advance once' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.has_org_role(p_org_id uuid, p_roles text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (SELECT FROM fieldmaps.organization_members m
    JOIN fieldmaps.profiles u ON u.user_id = m.user_id AND u.deleted_at IS NULL
    JOIN fieldmaps.organizations o ON o.id = m.organization_id AND o.deleted_at IS NULL
    WHERE m.organization_id = p_org_id AND m.user_id = fieldmaps.request_user_id() AND m.role = ANY(p_roles));
$$;

CREATE FUNCTION fieldmaps_private.has_project_role(p_project_id uuid, p_roles text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (SELECT FROM fieldmaps.projects p
    JOIN fieldmaps.organizations o ON o.id = p.organization_id AND o.deleted_at IS NULL
    WHERE p.id = p_project_id AND (
      ('manager' = ANY(p_roles) AND fieldmaps_private.has_org_role(p.organization_id, ARRAY['owner','admin']))
      OR EXISTS (SELECT FROM fieldmaps.project_memberships m
        JOIN fieldmaps.profiles u ON u.user_id = m.user_id AND u.deleted_at IS NULL
        WHERE m.project_id = p.id AND m.user_id = fieldmaps.request_user_id() AND m.role = ANY(p_roles))));
$$;

CREATE FUNCTION fieldmaps_private.lock_zone_authoring_site(p_project uuid, p_site uuid) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT (fieldmaps_private.lock_zone_site(p_project, p_site)).id::text;
$$;

CREATE TABLE fieldmaps.sites (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sites_code_check CHECK (((length(btrim(code)) >= 1) AND (length(btrim(code)) <= 100))),
    CONSTRAINT sites_description_check CHECK (((description IS NULL) OR (length(description) <= 2000))),
    CONSTRAINT sites_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200)))
);

CREATE FUNCTION fieldmaps_private.lock_zone_site(p_project uuid, p_site uuid) RETURNS fieldmaps.sites
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result fieldmaps.sites; org_id uuid;
BEGIN
  PERFORM fieldmaps_private.assert_active_user();
  SELECT organization_id INTO org_id FROM fieldmaps.projects WHERE id = p_project;
  IF org_id IS NULL THEN RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(org_id::text, 0));
  IF NOT fieldmaps_private.has_project_role(p_project, ARRAY['manager']) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  SELECT * INTO result FROM fieldmaps.sites WHERE project_id = p_project AND id = p_site FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007'; END IF;
  -- Refresh permission checks after every possible wait, before any mutation.
  PERFORM fieldmaps_private.assert_active_user();
  IF NOT fieldmaps_private.has_project_role(p_project, ARRAY['manager']) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  RETURN result;
END;
$$;

CREATE FUNCTION fieldmaps_private.my_collaborative_project_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p.id FROM fieldmaps.projects p
  WHERE NOT p.is_training AND p.id IN (SELECT fieldmaps_private.my_project_ids());
$$;

CREATE FUNCTION fieldmaps_private.my_org_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT m.organization_id FROM fieldmaps.organization_members m
  JOIN fieldmaps.profiles u ON u.user_id = m.user_id AND u.deleted_at IS NULL
  JOIN fieldmaps.organizations o ON o.id = m.organization_id AND o.deleted_at IS NULL
  WHERE m.user_id = fieldmaps.request_user_id();
$$;

CREATE FUNCTION fieldmaps_private.my_project_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p.id FROM fieldmaps.projects p JOIN fieldmaps.project_memberships m ON m.project_id = p.id
    JOIN fieldmaps.profiles u ON u.user_id = m.user_id AND u.deleted_at IS NULL
    JOIN fieldmaps.organizations o ON o.id = p.organization_id AND o.deleted_at IS NULL
    WHERE m.user_id = fieldmaps.request_user_id()
  UNION
  SELECT p.id FROM fieldmaps.projects p
    WHERE fieldmaps_private.has_org_role(p.organization_id, ARRAY['owner','admin']);
$$;

CREATE FUNCTION fieldmaps_private.normalize_zone_draft_values(p_zones jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE zone jsonb; result jsonb := '[]'; parts jsonb; part jsonb; ring jsonb;
  positions integer; total_positions integer := 0; ids uuid[] := '{}'; codes text[] := '{}'; zid uuid;
BEGIN
  IF p_zones IS NULL OR jsonb_typeof(p_zones) <> 'array' THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
  IF jsonb_array_length(p_zones) > 250 THEN PERFORM fieldmaps_private.reject_zone('too_complex'); END IF;
  FOR zone IN SELECT jsonb_array_elements(p_zones) LOOP
    IF jsonb_typeof(zone -> 'zone_label') = 'string' THEN
      zone := jsonb_set(zone, '{zone_label}', to_jsonb(fieldmaps_private.zone_trim(zone ->> 'zone_label')));
    END IF;
    IF jsonb_typeof(zone -> 'zone_id') = 'string' THEN
      zone := jsonb_set(zone, '{zone_id}', to_jsonb(lower(zone ->> 'zone_id')));
    END IF;
    IF zone #>> '{geometry,type}' NOT IN ('Polygon','MultiPolygon')
      OR jsonb_typeof(zone #> '{geometry,coordinates}') IS DISTINCT FROM 'array' THEN
      PERFORM fieldmaps_private.reject_zone('invalid_structure');
    END IF;
    parts := CASE WHEN zone #>> '{geometry,type}' = 'Polygon' THEN jsonb_build_array(zone #> '{geometry,coordinates}')
      ELSE zone #> '{geometry,coordinates}' END;
    positions := 0;
    FOR part IN SELECT jsonb_array_elements(parts) LOOP
      IF jsonb_typeof(part) <> 'array' THEN PERFORM fieldmaps_private.reject_zone('invalid_structure'); END IF;
      FOR ring IN SELECT jsonb_array_elements(part) LOOP
        IF jsonb_typeof(ring) <> 'array' THEN PERFORM fieldmaps_private.reject_zone('invalid_structure'); END IF;
        positions := positions + jsonb_array_length(ring);
        IF positions > 2000 THEN PERFORM fieldmaps_private.reject_zone('too_complex'); END IF;
      END LOOP;
    END LOOP;
    total_positions := total_positions + positions;
    IF total_positions > 20000 THEN PERFORM fieldmaps_private.reject_zone('too_complex'); END IF;
    IF NOT fieldmaps_private.valid_zone_draft(jsonb_build_array(zone)) THEN
      PERFORM fieldmaps_private.reject_zone('invalid_structure');
    END IF;
    zid := (zone ->> 'zone_id')::uuid;
    IF zid = ANY(ids) THEN PERFORM fieldmaps_private.reject_zone('duplicate_zone_id', ARRAY[zid]); END IF;
    IF zone ->> 'zone_code' = ANY(codes) THEN PERFORM fieldmaps_private.reject_zone('duplicate_code', ARRAY[zid]); END IF;
    ids := array_append(ids, zid); codes := array_append(codes, zone ->> 'zone_code');
    result := result || jsonb_build_array(zone);
  END LOOP;
  RETURN result;
END;
$$;

CREATE FUNCTION fieldmaps_private.normalize_zone_geometry(p_geometry jsonb, p_position_limit integer DEFAULT 2000) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    SET extra_float_digits TO '3'
    AS $$
DECLARE
  parts jsonb; part jsonb; shells jsonb := '[]'; holes jsonb; shell jsonb; normalized jsonb;
  original extensions.geometry; output_geom extensions.geometry;
BEGIN
  IF fieldmaps_private.zone_shape_position_count(p_geometry, p_position_limit) IS NULL THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
  original := extensions.ST_SetSRID(extensions.ST_GeomFromGeoJSON(p_geometry), 4326);
  IF extensions.ST_Area(extensions.ST_ConvexHull(original)) = 0 THEN
    PERFORM fieldmaps_private.reject_zone('zero_area');
  END IF;
  IF NOT extensions.ST_IsValid(original, 0) THEN
    PERFORM fieldmaps_private.reject_zone(CASE WHEN p_geometry ->> 'type' = 'Polygon'
      AND extensions.ST_IsValidReason(original) LIKE 'Self-intersection%'
      THEN 'self_intersection' ELSE 'invalid_topology' END);
  END IF;
  IF extensions.ST_Area(original) = 0 THEN PERFORM fieldmaps_private.reject_zone('zero_area'); END IF;
  parts := CASE WHEN p_geometry ->> 'type' = 'Polygon' THEN jsonb_build_array(p_geometry -> 'coordinates')
    ELSE p_geometry -> 'coordinates' END;
  FOR part IN SELECT jsonb_array_elements(parts) LOOP
    shell := fieldmaps_private.normalize_zone_ring(part -> 0, true);
    SELECT coalesce(jsonb_agg(ring ORDER BY fieldmaps_private.zone_sequence_key(ring)), '[]') INTO holes
    FROM (SELECT fieldmaps_private.normalize_zone_ring(value, false) ring
      FROM jsonb_array_elements(part) WITH ORDINALITY r(value, ordinal) WHERE ordinal > 1) h;
    shells := shells || jsonb_build_array(jsonb_build_array(shell) || holes);
  END LOOP;
  SELECT jsonb_build_object('type', 'MultiPolygon', 'coordinates', jsonb_agg(value
    ORDER BY fieldmaps_private.zone_sequence_key(value))) INTO normalized FROM jsonb_array_elements(shells);
  output_geom := extensions.ST_SetSRID(extensions.ST_GeomFromGeoJSON(normalized), 4326);
  IF NOT extensions.ST_IsValid(output_geom, 0) OR NOT extensions.ST_Equals(original, output_geom) THEN
    PERFORM fieldmaps_private.reject_zone('invalid_topology');
  END IF;
  RETURN normalized;
END;
$$;

CREATE FUNCTION fieldmaps_private.normalize_zone_ring(p_ring jsonb, p_shell boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    SET extra_float_digits TO '3'
    AS $$
DECLARE
  points jsonb[] := '{}'; point jsonb; previous jsonb; minimum_point jsonb; result jsonb[]; rotation jsonb[];
  area numeric := 0; count_points integer; best_key double precision[]; current_key double precision[];
BEGIN
  FOR point IN SELECT jsonb_array_elements(p_ring) LOOP
    point := jsonb_build_array((point ->> 0)::double precision + 0.0, (point ->> 1)::double precision + 0.0);
    IF previous IS DISTINCT FROM point THEN points := array_append(points, point); previous := point; END IF;
  END LOOP;
  count_points := cardinality(points);
  IF points[1] = points[count_points] THEN points := points[1:count_points - 1]; END IF;
  count_points := cardinality(points);
  FOR i IN 1..count_points LOOP
    point := points[CASE WHEN i = count_points THEN 1 ELSE i + 1 END];
    area := area + (points[i] ->> 0)::numeric * (point ->> 1)::numeric
      - (point ->> 0)::numeric * (points[i] ->> 1)::numeric;
  END LOOP;
  IF (area > 0) <> p_shell THEN
    SELECT array_agg(value ORDER BY ordinal DESC) INTO points FROM unnest(points) WITH ORDINALITY t(value, ordinal);
  END IF;
  SELECT value INTO minimum_point FROM unnest(points) value
    ORDER BY (value ->> 0)::double precision, (value ->> 1)::double precision LIMIT 1;
  FOR i IN 1..count_points LOOP
    IF points[i] <> minimum_point THEN CONTINUE; END IF;
    rotation := points[i:count_points] || points[1:i - 1];
    current_key := fieldmaps_private.zone_sequence_key(to_jsonb(rotation));
    IF best_key IS NULL OR current_key < best_key THEN result := rotation; best_key := current_key; END IF;
  END LOOP;
  RETURN to_jsonb(array_append(result, result[1]));
END;
$$;

CREATE FUNCTION fieldmaps_private.preserve_bound_observation_context() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (NEW.organization_id, NEW.project_id, NEW.site_id, NEW.form_version_id,
    extensions.ST_AsEWKB(NEW.geom), NEW.zone_code, NEW.round_type, NEW.first_round, NEW.placement_source, NEW.created_by, NEW.upload_hash)
    IS DISTINCT FROM (OLD.organization_id, OLD.project_id, OLD.site_id, OLD.form_version_id,
    extensions.ST_AsEWKB(OLD.geom), OLD.zone_code, OLD.round_type, OLD.first_round, OLD.placement_source, OLD.created_by, OLD.upload_hash) THEN
    RAISE EXCEPTION 'Historical observation context cannot change' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.preserve_draft_boundary() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF extensions.ST_AsEWKB(NEW.site_boundary) IS DISTINCT FROM extensions.ST_AsEWKB(OLD.site_boundary) THEN
    RAISE EXCEPTION 'Draft ground is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.preserve_observation_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF (NEW.package_id, NEW.zone_id)
    IS DISTINCT FROM (OLD.package_id, OLD.zone_id) THEN
    RAISE EXCEPTION 'Historical observation attribution cannot change' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.preserve_zone_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'Published zone history is immutable' USING ERRCODE = '23514';
END;
$$;

CREATE FUNCTION fieldmaps_private.preview_invitation(p_token_hash text, p_join_code_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE invitation fieldmaps.invitations;
BEGIN
  IF fieldmaps.request_user_id() IS NULL THEN RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006'; END IF;
  IF num_nonnulls(p_token_hash, p_join_code_hash) <> 1 THEN
    RAISE EXCEPTION 'invitation_invalid' USING ERRCODE = 'FM003';
  END IF;
  SELECT * INTO invitation FROM fieldmaps.invitations i
  WHERE i.token_hash = p_token_hash OR i.join_code_hash = p_join_code_hash;
  IF NOT FOUND OR invitation.revoked_at IS NOT NULL OR invitation.use_count >= invitation.max_uses
    OR NOT EXISTS (SELECT FROM fieldmaps.organizations WHERE id = invitation.organization_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'invitation_invalid' USING ERRCODE = 'FM003';
  END IF;
  IF invitation.expires_at <= now() THEN RAISE EXCEPTION 'invitation_expired' USING ERRCODE = 'FM004'; END IF;
  RETURN jsonb_build_object('organization_name', (SELECT name FROM fieldmaps.organizations WHERE id = invitation.organization_id),
    'project_name', (SELECT name FROM fieldmaps.projects WHERE id = invitation.project_id),
    'role', invitation.role, 'expires_at', invitation.expires_at);
END;
$$;

CREATE FUNCTION fieldmaps_private.publish_form_version(p_project_id uuid, p_form_version_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE target fieldmaps.form_versions;
BEGIN
  PERFORM fieldmaps_private.assert_active_user();
  SELECT * INTO target FROM fieldmaps.form_versions WHERE id = p_form_version_id FOR UPDATE;
  IF NOT FOUND OR target.project_id <> p_project_id THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007';
  END IF;
  IF NOT fieldmaps_private.has_project_role(p_project_id, ARRAY['manager']) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  IF target.state <> 'draft' THEN
    RAISE EXCEPTION 'conflict' USING ERRCODE = 'FM008';
  END IF;
  UPDATE fieldmaps.form_versions SET
    state = 'published',
    definition = pg_catalog.jsonb_set(target.definition, '{status}', '"published"', true),
    published_at = pg_catalog.clock_timestamp(),
    published_by = fieldmaps.request_user_id()
  WHERE id = p_form_version_id;
END;
$$;

CREATE FUNCTION fieldmaps_private.redeem_invitation(p_token_hash text, p_join_code_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE invitation fieldmaps.invitations;
BEGIN
  PERFORM fieldmaps_private.ensure_profile_row();
  IF num_nonnulls(p_token_hash, p_join_code_hash) <> 1 THEN
    RAISE EXCEPTION 'invitation_invalid' USING ERRCODE = 'FM003';
  END IF;
  SELECT * INTO invitation FROM fieldmaps.invitations i
  WHERE i.token_hash = p_token_hash OR i.join_code_hash = p_join_code_hash;
  IF NOT FOUND THEN RAISE EXCEPTION 'invitation_invalid' USING ERRCODE = 'FM003'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(invitation.organization_id::text, 0));
  PERFORM fieldmaps_private.preview_invitation(p_token_hash, p_join_code_hash);
  UPDATE fieldmaps.invitations i SET use_count = i.use_count + 1
  WHERE (i.token_hash = p_token_hash OR i.join_code_hash = p_join_code_hash)
    AND i.revoked_at IS NULL AND i.expires_at > now() AND i.use_count < i.max_uses
  RETURNING * INTO invitation;
  IF NOT FOUND THEN
    PERFORM fieldmaps_private.preview_invitation(p_token_hash, p_join_code_hash);
    RAISE EXCEPTION 'invitation_invalid' USING ERRCODE = 'FM003';
  END IF;
  IF invitation.email IS NOT NULL AND NOT EXISTS (SELECT FROM auth.users u
    WHERE u.id = fieldmaps.request_user_id() AND u.email_confirmed_at IS NOT NULL AND lower(u.email) = invitation.email) THEN
    RAISE EXCEPTION 'invitation_invalid' USING ERRCODE = 'FM003';
  END IF;
  IF invitation.project_id IS NULL THEN
    IF EXISTS (SELECT FROM fieldmaps.organization_members
      WHERE organization_id = invitation.organization_id AND user_id = fieldmaps.request_user_id()) THEN
      RAISE EXCEPTION 'invitation_invalid' USING ERRCODE = 'FM003';
    END IF;
    VALUES (invitation.organization_id, fieldmaps.request_user_id(), invitation.role, invitation.created_by);
  ELSE
    IF EXISTS (SELECT FROM fieldmaps.project_memberships
      WHERE project_id = invitation.project_id AND user_id = fieldmaps.request_user_id()) THEN
      RAISE EXCEPTION 'invitation_invalid' USING ERRCODE = 'FM003';
    END IF;
    VALUES (invitation.organization_id, fieldmaps.request_user_id(), 'member', invitation.created_by)
    ON CONFLICT DO NOTHING;
    VALUES (fieldmaps.request_user_id(), invitation.organization_id, invitation.project_id, invitation.role, invitation.created_by);
  END IF;
  RETURN jsonb_build_object('organization_id', invitation.organization_id, 'project_id', invitation.project_id, 'role', invitation.role);
END;
$$;

CREATE FUNCTION fieldmaps_private.reject_platform_membership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (SELECT FROM fieldmaps.organizations WHERE id = NEW.organization_id AND is_platform) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION fieldmaps_private.reject_zone(p_code text, p_ids uuid[] DEFAULT '{}'::uuid[], p_path text DEFAULT ''::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'validation_failed' USING ERRCODE = 'ZB001', DETAIL =
    jsonb_build_object('issues', jsonb_build_array(fieldmaps_private.zone_issue(p_code, p_ids, p_path)))::text;
END;
$$;

CREATE FUNCTION fieldmaps_private.remove_org_member(p_org_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN PERFORM fieldmaps_private.change_org_member(p_org_id, p_user_id, NULL); END;
$$;

CREATE FUNCTION fieldmaps_private.remove_project_member(p_project_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN PERFORM fieldmaps_private.change_project_member(p_project_id, p_user_id, NULL); END;
$$;

CREATE FUNCTION fieldmaps_private.resolve_zone_import_forms(p_project uuid, p_site uuid, p_expected uuid, p_body jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM fieldmaps_private.lock_zone_site(p_project,p_site);
  IF p_expected IS DISTINCT FROM fieldmaps_private.zone_current_package(p_site) THEN
    RAISE EXCEPTION 'publication_conflict' USING ERRCODE='ZB003';
  END IF;
  RETURN fieldmaps_private.zone_import_forms(p_project,p_expected,p_body);
END;
$$;

CREATE FUNCTION fieldmaps_private.retire_form_version(p_project_id uuid, p_form_version_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE target fieldmaps.form_versions;
BEGIN
  PERFORM fieldmaps_private.assert_active_user();
  SELECT * INTO target FROM fieldmaps.form_versions WHERE id = p_form_version_id FOR UPDATE;
  IF NOT FOUND OR target.project_id <> p_project_id THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007';
  END IF;
  IF NOT fieldmaps_private.has_project_role(p_project_id, ARRAY['manager']) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  IF target.state <> 'published' THEN
    RAISE EXCEPTION 'conflict' USING ERRCODE = 'FM008';
  END IF;
  UPDATE fieldmaps.form_versions SET state = 'retired' WHERE id = p_form_version_id;
END;
$$;

CREATE FUNCTION fieldmaps_private.revoke_invitation(p_org_id uuid, p_project_id uuid, p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE invitation fieldmaps.invitations;
BEGIN
  PERFORM fieldmaps_private.assert_active_user();
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_org_id::text, 0));
  SELECT * INTO invitation FROM fieldmaps.invitations WHERE id = p_id;
  IF NOT FOUND OR invitation.organization_id IS DISTINCT FROM p_org_id
    OR invitation.project_id IS DISTINCT FROM p_project_id THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007';
  END IF;
  IF (p_project_id IS NULL AND (NOT fieldmaps_private.has_org_role(p_org_id, ARRAY['owner','admin'])
      OR (invitation.role = 'admin' AND NOT fieldmaps_private.has_org_role(p_org_id, ARRAY['owner']))))
    OR (p_project_id IS NOT NULL AND NOT fieldmaps_private.has_project_role(p_project_id, ARRAY['manager'])) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  UPDATE fieldmaps.invitations SET revoked_at = coalesce(revoked_at, now()) WHERE id = p_id;
END;
$$;

CREATE FUNCTION fieldmaps_private.set_org_role(p_org_id uuid, p_user_id uuid, p_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM fieldmaps_private.assert_active_user();
  IF p_role IS NULL THEN RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006'; END IF;
  PERFORM fieldmaps_private.change_org_member(p_org_id, p_user_id, p_role);
END;
$$;

CREATE FUNCTION fieldmaps_private.set_project_role(p_project_id uuid, p_user_id uuid, p_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM fieldmaps_private.assert_active_user();
  IF p_role IS NULL THEN RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006'; END IF;
  PERFORM fieldmaps_private.change_project_member(p_project_id, p_user_id, p_role);
END;
$$;

CREATE FUNCTION fieldmaps_private.transfer_ownership(p_org_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE account_id uuid;
BEGIN
  IF fieldmaps.request_user_id() IS NULL THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  FOR account_id IN SELECT DISTINCT id FROM unnest(ARRAY[fieldmaps.request_user_id(), p_user_id]) AS users(id)
    WHERE id IS NOT NULL ORDER BY id LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('account:' || account_id::text, 0));
  END LOOP;
  PERFORM fieldmaps_private.ensure_profile_row();
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_org_id::text, 0));
  IF NOT fieldmaps_private.has_org_role(p_org_id, ARRAY['owner']) THEN
    RAISE EXCEPTION 'role_required' USING ERRCODE = 'FM006';
  END IF;
  IF NOT EXISTS (SELECT FROM fieldmaps.organization_members m JOIN fieldmaps.profiles u ON u.user_id = m.user_id
    WHERE m.organization_id = p_org_id AND m.user_id = p_user_id AND u.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007';
  END IF;
  IF NOT EXISTS (SELECT FROM fieldmaps.organization_members
      WHERE organization_id = p_org_id AND user_id = p_user_id AND role = 'owner')
    AND (SELECT count(*) FROM fieldmaps.organization_members WHERE user_id = p_user_id AND role = 'owner') >= 3 THEN
    RAISE EXCEPTION 'limit_reached' USING ERRCODE = 'FM001';
  END IF;
  UPDATE fieldmaps.organization_members SET role = 'owner', granted_by = fieldmaps.request_user_id(), granted_at = now()
  WHERE organization_id = p_org_id AND user_id = p_user_id;
  UPDATE fieldmaps.organization_members SET role = 'admin', granted_by = fieldmaps.request_user_id(), granted_at = now()
  WHERE organization_id = p_org_id AND user_id = fieldmaps.request_user_id() AND user_id <> p_user_id;
END;
$$;

CREATE FUNCTION fieldmaps_private.validate_zone_draft(p_project uuid, p_site uuid, p_draft uuid, p_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE draft fieldmaps.zone_drafts; play uuid;
BEGIN
  PERFORM fieldmaps_private.lock_zone_site(p_project, p_site);
  IF p_revision IS NULL OR p_revision < 1 THEN RAISE EXCEPTION 'precondition_required' USING ERRCODE = 'ZB006'; END IF;
  SELECT * INTO draft FROM fieldmaps.zone_drafts WHERE id = p_draft AND project_id = p_project AND site_id = p_site FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'FM007'; END IF;
  IF draft.revision <> p_revision THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE = 'ZB002'; END IF;
  IF draft.state <> 'draft' THEN RAISE EXCEPTION 'conflict' USING ERRCODE = 'FM008'; END IF;
  SELECT form_version_id INTO play FROM fieldmaps.site_packages WHERE id = draft.base_package_id;
  RETURN jsonb_build_object('draft_id', draft.id, 'revision', draft.revision) || fieldmaps_private.zone_validation(
    p_project, p_site, draft.zones, draft.site_boundary, play, draft.inventory_form_version_id, draft.change_note);
END;
$$;

CREATE FUNCTION fieldmaps_private.validate_zone_import(p_project uuid, p_site uuid, p_expected uuid, p_body jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE site fieldmaps.sites; base fieldmaps.site_packages; imported jsonb; ground extensions.geometry; forms jsonb;
BEGIN
  site := fieldmaps_private.lock_zone_site(p_project, p_site);
  IF NOT coalesce(p_body ? 'expected_current_package_id',false) THEN
    RAISE EXCEPTION 'precondition_required' USING ERRCODE='ZB006'; END IF;
  IF p_expected IS DISTINCT FROM fieldmaps_private.zone_current_package(p_site) THEN
    RAISE EXCEPTION 'publication_conflict' USING ERRCODE='ZB003';
  END IF;
  SELECT * INTO base FROM fieldmaps.site_packages WHERE id=p_expected AND project_id=p_project AND site_id=p_site;
  IF p_body->>'site_id' IS DISTINCT FROM p_site::text THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
  forms := fieldmaps_private.zone_import_forms(p_project,base.id,p_body);
  imported := fieldmaps_private.zone_import_input(p_body);
  ground := extensions.ST_GeomFromGeoJSON(fieldmaps_private.normalize_zone_geometry(imported->'ground',2147483647));
  RETURN fieldmaps_private.zone_validation(p_project,p_site,
    fieldmaps_private.normalize_zone_draft_values(imported->'zones'),ground,(forms #>> '{play,form_version_id}')::uuid,
    (forms #>> '{inventory,form_version_id}')::uuid,p_body->>'change_note');
END;
$$;

CREATE FUNCTION fieldmaps_private.zone_coordinate_bytes(p_coordinates jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
DECLARE value jsonb; result text := ''; separator text := '';
BEGIN
  IF jsonb_typeof(p_coordinates) = 'number' THEN
    RETURN fieldmaps_private.zone_number(p_coordinates::text::double precision);
  END IF;
  IF jsonb_typeof(p_coordinates) <> 'array' THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
  FOR value IN SELECT jsonb_array_elements(p_coordinates) LOOP
    result := result || separator || fieldmaps_private.zone_coordinate_bytes(value);
    separator := ',';
  END LOOP;
  RETURN '[' || result || ']';
END;
$$;

CREATE FUNCTION fieldmaps_private.zone_current_package(p_site uuid) RETURNS uuid
LANGUAGE sql STABLE SET search_path = '' AS $$
 SELECT current_package_id FROM fieldmaps.site_zone_state WHERE site_id=p_site;
$$;

CREATE FUNCTION fieldmaps_private.zone_geom_json(p_geometry extensions.geometry) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    SET extra_float_digits TO '3'
    AS $$
  SELECT jsonb_build_object('type', 'MultiPolygon', 'coordinates', jsonb_agg(rings ORDER BY polygon))
  FROM (SELECT polygon, jsonb_agg(points ORDER BY ring) rings FROM
    (SELECT (d.path)[1] polygon, (d.path)[2] ring,
      jsonb_agg(jsonb_build_array(extensions.ST_X(d.geom), extensions.ST_Y(d.geom)) ORDER BY (d.path)[3]) points
    FROM extensions.ST_DumpPoints(extensions.ST_Multi(p_geometry)) d GROUP BY (d.path)[1], (d.path)[2]) r
    GROUP BY polygon) p;
$$;

CREATE FUNCTION fieldmaps_private.zone_geometry_digest(p_normalized jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  SELECT encode(sha256(convert_to('{"coordinates":' ||
    fieldmaps_private.zone_coordinate_bytes(p_normalized -> 'coordinates') || ',"type":"MultiPolygon"}', 'UTF8')), 'hex');
$$;

CREATE FUNCTION fieldmaps_private.zone_import_forms(p_project uuid, p_base uuid, p_body jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE play fieldmaps.form_versions; inventory fieldmaps.form_versions; inventory_id uuid;
BEGIN
  IF jsonb_typeof(p_body->'form_version') IS DISTINCT FROM 'string'
    OR (p_body ? 'inventory_form_version' AND jsonb_typeof(p_body->'inventory_form_version') NOT IN ('string','null')) THEN
    PERFORM fieldmaps_private.reject_zone('form_not_in_package');
  END IF;
  SELECT * INTO play FROM fieldmaps.form_versions WHERE project_id=p_project AND code=p_body->>'form_version';
  IF NOT FOUND THEN PERFORM fieldmaps_private.reject_zone('form_not_in_package'); END IF;
  IF p_body ? 'inventory_form_version' THEN
    IF p_body->>'inventory_form_version' IS NOT NULL THEN
      SELECT id INTO inventory_id FROM fieldmaps.form_versions
        WHERE project_id=p_project AND code=p_body->>'inventory_form_version';
      IF NOT FOUND THEN PERFORM fieldmaps_private.reject_zone('form_not_in_package'); END IF;
    END IF;
  ELSE
    SELECT inventory_form_version_id INTO inventory_id FROM fieldmaps.site_packages
      WHERE project_id=p_project AND id=p_base;
  END IF;
  -- Match publication's deterministic form lock order; retirement holds an incompatible row lock.
  PERFORM 1 FROM fieldmaps.form_versions WHERE id IN (play.id,inventory_id) ORDER BY id FOR SHARE;
  SELECT * INTO play FROM fieldmaps.form_versions WHERE id=play.id AND state='published';
  IF NOT FOUND THEN PERFORM fieldmaps_private.reject_zone('form_not_in_package'); END IF;
  IF inventory_id IS NOT NULL THEN
    SELECT * INTO inventory FROM fieldmaps.form_versions WHERE id=inventory_id AND project_id=p_project AND state='published';
    IF NOT FOUND THEN PERFORM fieldmaps_private.reject_zone('form_not_in_package'); END IF;
  END IF;
  RETURN jsonb_build_object('play',jsonb_build_object('form_version_id',play.id,'form_version',play.code),
    'inventory',CASE WHEN inventory_id IS NULL THEN NULL ELSE
      jsonb_build_object('form_version_id',inventory.id,'form_version',inventory.code) END);
END;
$$;

CREATE FUNCTION fieldmaps_private.zone_import_input(p_body jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE mapping jsonb; feature jsonb; zones jsonb := '[]'; ground jsonb;
BEGIN
  IF jsonb_typeof(p_body -> 'zone_identity_map') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_body #> '{layers,zones,features}') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_body #> '{layers,ground,features}') IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_body -> 'zone_identity_map') NOT BETWEEN 1 AND 250
    OR jsonb_array_length(p_body -> 'zone_identity_map') <> jsonb_array_length(p_body #> '{layers,zones,features}') THEN
    PERFORM fieldmaps_private.reject_zone('identity_conflict');
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_body #> '{layers,ground,features}')
    WHERE value #>> '{properties,kind}' = 'site') <> 1 THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
  SELECT value -> 'geometry' INTO ground FROM jsonb_array_elements(p_body #> '{layers,ground,features}')
    WHERE value #>> '{properties,kind}' = 'site';
  IF EXISTS (SELECT FROM jsonb_array_elements(p_body -> 'zone_identity_map')
    WHERE jsonb_typeof(value -> 'source_feature_id') IS DISTINCT FROM 'string'
      OR length(value ->> 'source_feature_id') NOT BETWEEN 1 AND 200)
    OR EXISTS (SELECT FROM jsonb_array_elements(p_body #> '{layers,zones,features}')
    WHERE jsonb_typeof(value #> '{properties,id}') IS DISTINCT FROM 'string'
      OR length(value #>> '{properties,id}') NOT BETWEEN 1 AND 200) THEN
    PERFORM fieldmaps_private.reject_zone('identity_conflict');
  END IF;
  IF EXISTS (SELECT FROM jsonb_array_elements(p_body -> 'zone_identity_map') GROUP BY value -> 'source_feature_id' HAVING count(*) > 1)
    OR EXISTS (SELECT FROM jsonb_array_elements(p_body #> '{layers,zones,features}') GROUP BY value #> '{properties,id}' HAVING count(*) > 1) THEN
    PERFORM fieldmaps_private.reject_zone('identity_conflict');
  END IF;
  FOR mapping IN SELECT jsonb_array_elements(p_body -> 'zone_identity_map') LOOP
    SELECT value INTO feature FROM jsonb_array_elements(p_body #> '{layers,zones,features}')
      WHERE value #> '{properties,id}' = mapping -> 'source_feature_id';
    IF NOT FOUND THEN PERFORM fieldmaps_private.reject_zone('identity_conflict'); END IF;
    zones := zones || jsonb_build_array(jsonb_build_object('zone_id', mapping -> 'zone_id',
      'zone_code', mapping -> 'zone_code', 'zone_label', feature #> '{properties,name}', 'geometry', feature -> 'geometry'));
  END LOOP;
  RETURN jsonb_build_object('ground', ground, 'zones', zones);
END;
$$;

CREATE FUNCTION fieldmaps_private.zone_issue(p_code text, p_ids uuid[] DEFAULT '{}'::uuid[], p_path text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT jsonb_build_object('code', p_code, 'zone_ids', to_jsonb(p_ids), 'path', p_path, 'message', p_code);
$$;

CREATE FUNCTION fieldmaps_private.zone_number(p_value double precision) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    SET extra_float_digits TO '3'
    AS $$
DECLARE
  bits bytea := float8send(abs(p_value));
  binary_exponent integer := ((get_byte(bits, 0) & 127) << 4) + (get_byte(bits, 1) >> 4);
  mantissa numeric := get_byte(bits, 1) & 15;
  exact_value numeric;
  factor numeric := 1;
  multiplier numeric;
  power_count integer;
  decimal_exponent integer;
  scale_digits integer;
  candidate numeric;
  unit_value numeric;
  digits text;
  sign_text text := CASE WHEN p_value < 0 THEN '-' ELSE '' END;
BEGIN
  IF p_value = 0 THEN RETURN '0'; END IF;
  IF p_value NOT BETWEEN -180 AND 180 THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
  FOR i IN 2..7 LOOP mantissa := mantissa * 256 + get_byte(bits, i); END LOOP;
  IF binary_exponent = 0 THEN binary_exponent := -1074;
  ELSE mantissa := mantissa + 4503599627370496; binary_exponent := binary_exponent - 1075; END IF;
  power_count := abs(binary_exponent);
  multiplier := CASE WHEN binary_exponent < 0 THEN 5 ELSE 2 END;
  WHILE power_count > 0 LOOP
    IF power_count % 2 = 1 THEN factor := factor * multiplier; END IF;
    multiplier := multiplier * multiplier;
    power_count := power_count / 2;
  END LOOP;
  exact_value := mantissa * factor;
  IF binary_exponent < 0 THEN
    exact_value := (exact_value::text || 'e' || binary_exponent)::numeric;
  END IF;
  digits := split_part(exact_value::text, '.', 1);
  IF digits <> '0' THEN decimal_exponent := length(digits) - 1;
  ELSE decimal_exponent := -length(substring(exact_value::text FROM '^0\.(0*)')) - 1; END IF;
  FOR significant_digits IN 1..17 LOOP
    scale_digits := significant_digits - 1 - decimal_exponent;
    unit_value := ('1e' || (-scale_digits))::numeric;
    candidate := round(exact_value, scale_digits);
    -- ECMAScript chooses the nearest shortest decimal, with an even final digit on a tie.
    IF abs(candidate - exact_value) = unit_value / 2 AND mod(candidate / unit_value, 2) = 1 THEN
      candidate := candidate - unit_value;
    END IF;
    EXIT WHEN candidate::double precision = abs(p_value);
  END LOOP;
  digits := trim_scale(candidate)::text;
  IF candidate >= 0.000001 THEN RETURN sign_text || digits; END IF;
  decimal_exponent := -length(substring(digits FROM '^0\.(0*)')) - 1;
  digits := regexp_replace(digits, '^0\.0*', '');
  RETURN sign_text || left(digits, 1) || CASE WHEN length(digits) > 1 THEN '.' || substring(digits FROM 2) ELSE '' END
    || 'e' || decimal_exponent;
END;
$$;

CREATE FUNCTION fieldmaps_private.zone_position_count(p_geometry jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  SELECT fieldmaps_private.zone_shape_position_count(p_geometry, 2000);
$$;

CREATE FUNCTION fieldmaps_private.zone_sequence_key(p_value jsonb) RETURNS double precision[]
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
DECLARE value jsonb; result double precision[] := '{}';
BEGIN
  IF jsonb_typeof(p_value) = 'number' THEN RETURN ARRAY[p_value::text::double precision]; END IF;
  FOR value IN SELECT jsonb_array_elements(p_value) LOOP
    result := result || fieldmaps_private.zone_sequence_key(value);
  END LOOP;
  RETURN result || '-Infinity'::double precision;
END;
$$;

CREATE FUNCTION fieldmaps_private.zone_shape_position_count(p_geometry jsonb, p_limit integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
DECLARE parts jsonb; part jsonb; ring jsonb; position jsonb; positions integer := 0;
BEGIN
  IF jsonb_typeof(p_geometry) <> 'object' OR NOT p_geometry ?& ARRAY['type','coordinates']
    OR (SELECT count(*) FROM jsonb_object_keys(p_geometry)) <> 2 THEN RETURN NULL; END IF;
  CASE p_geometry ->> 'type'
    WHEN 'Polygon' THEN parts := jsonb_build_array(p_geometry -> 'coordinates');
    WHEN 'MultiPolygon' THEN parts := p_geometry -> 'coordinates';
    ELSE RETURN NULL;
  END CASE;
  IF jsonb_typeof(parts) <> 'array' OR jsonb_array_length(parts) = 0 THEN RETURN NULL; END IF;
  FOR part IN SELECT jsonb_array_elements(parts) LOOP
    IF jsonb_typeof(part) <> 'array' OR jsonb_array_length(part) = 0 THEN RETURN NULL; END IF;
    FOR ring IN SELECT jsonb_array_elements(part) LOOP
      IF jsonb_typeof(ring) <> 'array' OR jsonb_array_length(ring) < 4 THEN RETURN NULL; END IF;
      positions := positions + jsonb_array_length(ring);
      IF positions > p_limit OR ring -> 0 <> ring -> -1
        OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(ring)) < 3 THEN RETURN NULL; END IF;
      FOR position IN SELECT jsonb_array_elements(ring) LOOP
        IF jsonb_typeof(position) <> 'array' OR jsonb_array_length(position) <> 2
          OR jsonb_typeof(position -> 0) <> 'number' OR jsonb_typeof(position -> 1) <> 'number' THEN RETURN NULL; END IF;
        IF (position ->> 0)::numeric NOT BETWEEN -180 AND 180
          OR (position ->> 1)::numeric NOT BETWEEN -90 AND 90 THEN RETURN NULL; END IF;
      END LOOP;
    END LOOP;
  END LOOP;
  RETURN positions;
END;
$$;

CREATE FUNCTION fieldmaps_private.zone_trim(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  SELECT btrim(p_value, chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(28)||chr(29)||chr(30)||chr(31)||chr(32)
    ||chr(133)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)
    ||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288));
$$;

CREATE FUNCTION fieldmaps_private.zone_validation(p_project uuid, p_site uuid, p_zones jsonb, p_ground extensions.geometry, p_play uuid, p_inventory uuid, p_note text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    SET extra_float_digits TO '3'
    AS $$
DECLARE
  issues jsonb := '[]'; warnings jsonb := '[]'; normalized jsonb := '[]'; summaries jsonb := '[]';
  zone jsonb; canonical jsonb; shape extensions.geometry; prior_shape extensions.geometry;
  prior_shapes extensions.geometry[] := '{}'; prior_ids uuid[] := '{}';
  coverage extensions.geometry; extent extensions.box3d; anchor extensions.geometry;
  area double precision; gap double precision := NULL; detail text; zid uuid; path text; ground_valid boolean; prior fieldmaps.package_zones; digest text; change text; removed record;
BEGIN
  IF NOT coalesce(fieldmaps_private.valid_zone_draft(p_zones), false) THEN
    PERFORM fieldmaps_private.reject_zone('invalid_structure');
  END IF;
  IF jsonb_array_length(p_zones) = 0 THEN
    issues := issues || jsonb_build_array(fieldmaps_private.zone_issue('empty_zone_set'));
  END IF;
  ground_valid := coalesce(NOT extensions.ST_IsEmpty(p_ground) AND extensions.ST_IsValid(p_ground, 0)
    AND extensions.ST_NDims(p_ground) = 2 AND extensions.ST_SRID(p_ground) = 4326, false);
  IF NOT ground_valid THEN issues := issues || jsonb_build_array(fieldmaps_private.zone_issue('invalid_topology')); END IF;
  IF NOT EXISTS (SELECT FROM fieldmaps.form_versions WHERE project_id = p_project AND id = p_play AND state = 'published')
    OR (p_inventory IS NOT NULL AND NOT EXISTS (SELECT FROM fieldmaps.form_versions
      WHERE project_id = p_project AND id = p_inventory AND state = 'published')) THEN
    issues := issues || jsonb_build_array(fieldmaps_private.zone_issue('form_not_in_package'));
  END IF;
  coverage := p_ground;
  FOR zone, path IN SELECT value, '/zones/' || (ordinal - 1)::text || '/geometry'
    FROM jsonb_array_elements(p_zones) WITH ORDINALITY z(value, ordinal) LOOP
    zid := (zone ->> 'zone_id')::uuid;
    IF EXISTS (SELECT FROM fieldmaps.zone_identities WHERE id = zid
      AND (project_id <> p_project OR site_id <> p_site OR code <> zone ->> 'zone_code'))
      OR EXISTS (SELECT FROM fieldmaps.zone_identities WHERE site_id = p_site
        AND code = zone ->> 'zone_code' AND id <> zid) THEN
      issues := issues || jsonb_build_array(fieldmaps_private.zone_issue('identity_conflict', ARRAY[zid], path));
    END IF;
    BEGIN
      canonical := fieldmaps_private.normalize_zone_geometry(zone -> 'geometry');
    EXCEPTION WHEN SQLSTATE 'ZB001' THEN
      GET STACKED DIAGNOSTICS detail = PG_EXCEPTION_DETAIL;
      issues := issues || jsonb_build_array(fieldmaps_private.zone_issue(detail::jsonb #>> '{issues,0,code}', ARRAY[zid], path));
      summaries := summaries || jsonb_build_array(jsonb_build_object('zone_id', zid, 'area_m2', NULL,
        'extent', NULL, 'display_anchor', NULL,'geometry_sha256',NULL,'change',NULL));
      CONTINUE;
    END;
    shape := extensions.ST_GeomFromGeoJSON(canonical);
    IF ground_valid AND NOT extensions.ST_Covers(p_ground, shape) THEN
      issues := issues || jsonb_build_array(fieldmaps_private.zone_issue('outside_site', ARRAY[zid], path));
    END IF;
    FOR i IN 1..cardinality(prior_shapes) LOOP
      prior_shape := prior_shapes[i];
      IF shape OPERATOR(extensions.&&) prior_shape AND extensions.ST_Relate(shape, prior_shape, '2********') THEN
        issues := issues || jsonb_build_array(fieldmaps_private.zone_issue('interior_overlap',
          ARRAY[prior_ids[i], zid], path));
      END IF;
    END LOOP;
    prior_shapes := array_append(prior_shapes, shape);
    prior_ids := array_append(prior_ids, zid);
    extent := shape::extensions.box3d;
    IF extensions.ST_YMin(extent) < -85 OR extensions.ST_YMax(extent) > 85
      OR extensions.ST_XMax(extent) - extensions.ST_XMin(extent) > 1
      OR extensions.ST_YMax(extent) - extensions.ST_YMin(extent) > 1 THEN
      issues := issues || jsonb_build_array(fieldmaps_private.zone_issue('unsupported_extent', ARRAY[zid], path));
    END IF;
    coverage := extensions.ST_Collect(coverage, shape);
    anchor := extensions.ST_PointOnSurface(shape);
    area := extensions.ST_Area(shape::extensions.geography);
    IF area < 1 THEN warnings := warnings || jsonb_build_array(fieldmaps_private.zone_issue('small_zone', ARRAY[zid], path)); END IF;
    normalized := normalized || jsonb_build_array(zone || jsonb_build_object('geometry', canonical,
      'display_anchor', jsonb_build_array(extensions.ST_X(anchor), extensions.ST_Y(anchor)),
      'geometry_sha256', fieldmaps_private.zone_geometry_digest(canonical)));
    digest:=fieldmaps_private.zone_geometry_digest(canonical);
    SELECT * INTO prior FROM fieldmaps.package_zones WHERE package_id=fieldmaps_private.zone_current_package(p_site) AND zone_id=zid;
    change:=CASE WHEN NOT FOUND THEN 'added' WHEN prior.geometry_sha256<>digest THEN 'geometry_changed'
      WHEN prior.label IS DISTINCT FROM zone->>'zone_label' THEN 'label_changed' ELSE 'unchanged' END;
    summaries := summaries || jsonb_build_array(jsonb_build_object('zone_id', zid, 'area_m2', area,
      'extent', jsonb_build_object('west', extensions.ST_XMin(extent), 'south', extensions.ST_YMin(extent),
        'east', extensions.ST_XMax(extent), 'north', extensions.ST_YMax(extent)),
      'display_anchor', jsonb_build_array(extensions.ST_X(anchor), extensions.ST_Y(anchor)),
      'geometry_sha256',digest,'change',change));
  END LOOP;
  IF ground_valid THEN
    extent := coverage::extensions.box3d;
    IF extensions.ST_YMin(extent) < -85 OR extensions.ST_YMax(extent) > 85
      OR extensions.ST_XMax(extent) - extensions.ST_XMin(extent) > 1
      OR extensions.ST_YMax(extent) - extensions.ST_YMin(extent) > 1 THEN
      issues := issues || jsonb_build_array(fieldmaps_private.zone_issue('unsupported_extent'));
    END IF;
    IF jsonb_array_length(normalized) > 0 THEN
      SELECT extensions.ST_Area(extensions.ST_Difference(p_ground,
        extensions.ST_UnaryUnion(extensions.ST_Collect(extensions.ST_GeomFromGeoJSON(value -> 'geometry'))))::extensions.geography)
        INTO gap FROM jsonb_array_elements(normalized);
      IF gap > 0 THEN warnings := warnings || jsonb_build_array(fieldmaps_private.zone_issue('site_gap')); END IF;
    END IF;
  END IF;
  FOR removed IN SELECT * FROM fieldmaps.package_zones z
    WHERE z.package_id=fieldmaps_private.zone_current_package(p_site) AND NOT EXISTS
      (SELECT FROM jsonb_array_elements(p_zones) WHERE (value->>'zone_id')::uuid=z.zone_id) LOOP
    extent:=removed.geom::extensions.box3d;
    summaries:=summaries||jsonb_build_array(jsonb_build_object('zone_id',removed.zone_id,
      'area_m2',extensions.ST_Area(removed.geom::extensions.geography),
      'extent',jsonb_build_object('west',extensions.ST_XMin(extent),'south',extensions.ST_YMin(extent),
        'east',extensions.ST_XMax(extent),'north',extensions.ST_YMax(extent)),
      'display_anchor',jsonb_build_array(extensions.ST_X(removed.display_anchor),extensions.ST_Y(removed.display_anchor)),
      'geometry_sha256',removed.geometry_sha256,'change','removed'));
  END LOOP;
  -- A rejected proposed zone has no accepted derived metadata. Removed summaries
  -- still describe the retained valid snapshot of the current package.
  SELECT coalesce(jsonb_agg(CASE WHEN summary->>'change' IS DISTINCT FROM 'removed' AND EXISTS
    (SELECT FROM jsonb_array_elements(issues) issue WHERE issue->'zone_ids' ? (summary->>'zone_id')
      OR (issue->>'code'='unsupported_extent' AND issue->'zone_ids'='[]'::jsonb))
    THEN jsonb_build_object('zone_id',summary->'zone_id','area_m2',NULL,'extent',NULL,
      'display_anchor',NULL,'geometry_sha256',NULL,'change',NULL) ELSE summary END ORDER BY ordinal),'[]'::jsonb)
    INTO summaries FROM jsonb_array_elements(summaries) WITH ORDINALITY items(summary,ordinal);
  RETURN jsonb_build_object('ready', issues = '[]', 'issues', issues, 'warnings', warnings,
    'zones', summaries, 'canonical_zones', normalized, 'site_gap_area_m2', gap);
END;
$$;

CREATE TABLE fieldmaps.form_versions (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    code text NOT NULL,
    definition jsonb NOT NULL,
    form_id uuid NOT NULL,
    version integer NOT NULL,
    state text DEFAULT 'published'::text NOT NULL,
    schema_version integer DEFAULT 1 NOT NULL,
    published_at timestamp with time zone,
    published_by uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT form_versions_check CHECK (((state <> 'published'::text) OR (published_at IS NOT NULL))),
    CONSTRAINT form_versions_code_check CHECK (((length(btrim(code)) >= 1) AND (length(btrim(code)) <= 100))),
    CONSTRAINT form_versions_definition_check CHECK ((jsonb_typeof(definition) = 'object'::text)),
    CONSTRAINT form_versions_schema_version_check CHECK ((schema_version > 0)),
    CONSTRAINT form_versions_state_check CHECK ((state = ANY (ARRAY['draft'::text, 'published'::text, 'retired'::text]))),
    CONSTRAINT form_versions_version_check CHECK ((version > 0))
);

CREATE TABLE fieldmaps.forms (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT forms_code_check CHECK ((code ~ '^[a-z0-9](?:[a-z0-9-]{0,78}[a-z0-9])?$'::text)),
    CONSTRAINT forms_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200)))
);

CREATE TABLE fieldmaps.invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid,
    email text,
    role text NOT NULL,
    token_hash text,
    join_code_hash text,
    expires_at timestamp with time zone NOT NULL,
    max_uses integer NOT NULL,
    use_count integer DEFAULT 0 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    CONSTRAINT invitations_check CHECK (((use_count >= 0) AND (use_count <= max_uses))),
    CONSTRAINT invitations_check1 CHECK (((token_hash IS NOT NULL) OR (join_code_hash IS NOT NULL))),
    CONSTRAINT invitations_check2 CHECK ((((project_id IS NULL) AND (role = ANY (ARRAY['member'::text, 'admin'::text]))) OR ((project_id IS NOT NULL) AND (role = ANY (ARRAY['observer'::text, 'viewer'::text, 'manager'::text]))))),
    CONSTRAINT invitations_email_check CHECK ((email = lower(email))),
    CONSTRAINT invitations_expires_at_check CHECK (isfinite(expires_at)),
    CONSTRAINT invitations_join_code_hash_check CHECK ((join_code_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT invitations_max_uses_check CHECK ((max_uses > 0)),
    CONSTRAINT invitations_token_hash_check CHECK ((token_hash ~ '^[a-f0-9]{64}$'::text))
);

CREATE TABLE fieldmaps.observations (
    id uuid NOT NULL,
    qgis_id bigint NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    site_id uuid NOT NULL,
    form_version_id uuid NOT NULL,
    observer_code text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    deleted_at timestamp with time zone,
    geom extensions.geometry(Point,4326),
    answers jsonb NOT NULL,
    created_by uuid NOT NULL,
    upload_hash text NOT NULL,
    zone_code text NOT NULL,
    round_type text NOT NULL,
    first_round boolean,
    placement_source text NOT NULL,
    package_id uuid NOT NULL,
    zone_id uuid NOT NULL,
    CONSTRAINT observations_answers_check CHECK ((jsonb_typeof(answers) = 'object'::text)),
    CONSTRAINT observations_deleted_at_check CHECK (((deleted_at IS NULL) OR isfinite(deleted_at))),
    CONSTRAINT observations_geom_check CHECK ((NOT extensions.st_isempty(geom))),
    CONSTRAINT observations_geom_check1 CHECK ((((extensions.st_x(geom) >= ('-180'::integer)::double precision) AND (extensions.st_x(geom) <= (180)::double precision)) AND ((extensions.st_y(geom) >= ('-90'::integer)::double precision) AND (extensions.st_y(geom) <= (90)::double precision)))),
    CONSTRAINT observations_observed_at_check CHECK (isfinite(observed_at)),
    CONSTRAINT observations_observer_code_check CHECK (((length(btrim(observer_code)) >= 1) AND (length(btrim(observer_code)) <= 12))),
    CONSTRAINT observations_placement_source_check CHECK ((placement_source = ANY (ARRAY['hand'::text, 'zone'::text]))),
    CONSTRAINT observations_revision_check CHECK ((revision > 0)),
    CONSTRAINT observations_round_type_check CHECK ((round_type = ANY (ARRAY['standard'::text, 'reliability'::text, 'inventory'::text]))),
    CONSTRAINT observations_upload_hash_check CHECK ((upload_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT observations_zone_code_check CHECK (((zone_code IS NULL) OR ((length(btrim(zone_code)) >= 1) AND (length(btrim(zone_code)) <= 100)))),
    CONSTRAINT observation_spatial_support CHECK (
      (round_type IN ('standard','reliability') AND placement_source='hand' AND first_round IS NOT NULL AND geom IS NOT NULL)
      OR (round_type='inventory' AND placement_source='zone' AND first_round IS NULL AND geom IS NULL))
);

ALTER TABLE fieldmaps.observations ALTER COLUMN qgis_id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME fieldmaps.observations_qgis_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE fieldmaps.organization_members (
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL,
    granted_by uuid,
    granted_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT organization_members_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'admin'::text, 'member'::text])))
);

CREATE TABLE fieldmaps.package_checks (
    package_id uuid NOT NULL,
    "position" integer NOT NULL,
    step text NOT NULL,
    state text NOT NULL,
    detail text NOT NULL,
    CONSTRAINT package_checks_detail_check CHECK (((length(btrim(detail)) >= 1) AND (length(btrim(detail)) <= 2000))),
    CONSTRAINT package_checks_position_check CHECK (("position" >= 0)),
    CONSTRAINT package_checks_state_check CHECK ((state = ANY (ARRAY['passed'::text, 'warning'::text, 'blocked'::text, 'skipped'::text]))),
    CONSTRAINT package_checks_step_check CHECK ((step = ANY (ARRAY['source-project'::text, 'layer-sources'::text, 'coordinate-reference'::text, 'imagery-licence'::text, 'archive'::text])))
);

CREATE TABLE fieldmaps.package_zones (
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    site_id uuid NOT NULL,
    package_id uuid NOT NULL,
    zone_id uuid NOT NULL,
    label text NOT NULL,
    geom extensions.geometry(MultiPolygon,4326) NOT NULL,
    display_anchor extensions.geometry(Point,4326) NOT NULL,
    geometry_sha256 text NOT NULL,
    canonical_geometry jsonb NOT NULL,
    CONSTRAINT package_zones_check CHECK (((NOT extensions.st_isempty(display_anchor)) AND (extensions.st_ndims(display_anchor) = 2) AND extensions.st_covers(geom, display_anchor))),
    CONSTRAINT package_zones_geom_check CHECK ((extensions.st_isvalid(geom) AND (NOT extensions.st_isempty(geom)) AND (extensions.st_ndims(geom) = 2) AND (extensions.st_npoints(geom) <= 2000) AND (extensions.st_xmin((geom)::extensions.box3d) >= ('-180'::integer)::double precision) AND (extensions.st_xmax((geom)::extensions.box3d) <= (180)::double precision) AND (extensions.st_ymin((geom)::extensions.box3d) >= ('-85'::integer)::double precision) AND (extensions.st_ymax((geom)::extensions.box3d) <= (85)::double precision) AND ((extensions.st_xmax((geom)::extensions.box3d) - extensions.st_xmin((geom)::extensions.box3d)) <= (1)::double precision) AND ((extensions.st_ymax((geom)::extensions.box3d) - extensions.st_ymin((geom)::extensions.box3d)) <= (1)::double precision))),
    CONSTRAINT package_zones_geometry_sha256_check CHECK ((geometry_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT package_zones_label_check CHECK (((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 200)))
);

CREATE TABLE fieldmaps.project_memberships (
    user_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    role text NOT NULL,
    granted_by uuid,
    granted_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT project_memberships_role_check CHECK ((role = ANY (ARRAY['observer'::text, 'manager'::text, 'viewer'::text])))
);

CREATE TABLE fieldmaps.site_zone_state (
    site_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    current_package_id uuid NOT NULL,
    revision integer NOT NULL,
    enabled_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT site_zone_state_revision_check CHECK ((revision > 0))
);

CREATE TABLE fieldmaps.zone_identities (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    site_id uuid NOT NULL,
    code text NOT NULL COLLATE pg_catalog."C",
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT zone_identities_code_check CHECK ((((length(code) >= 1) AND (length(code) <= 100)) AND (code ~ '^[A-Za-z0-9][A-Za-z0-9_.-]*$'::text)))
);

CREATE TABLE fieldmaps.zone_publications (
    request_id uuid NOT NULL,
    created_by uuid NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    site_id uuid NOT NULL,
    operation text DEFAULT 'draft_publish'::text NOT NULL,
    draft_id uuid,
    draft_revision bigint,
    expected_current_package_id uuid,
    request_hash text NOT NULL,
    request jsonb NOT NULL,
    published_package_id uuid NOT NULL,
    identity_map jsonb NOT NULL,
    change_note text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT zone_publications_change_note_check CHECK ((length(change_note) <= 2000)),
    CONSTRAINT zone_publications_check CHECK (((draft_id IS NULL) = (draft_revision IS NULL))),
    CONSTRAINT zone_publications_check1 CHECK (((operation <> 'draft_publish'::text) OR (draft_id IS NOT NULL))),
    CONSTRAINT zone_publications_draft_revision_check CHECK ((draft_revision > 0)),
    CONSTRAINT zone_publications_identity_map_check CHECK (((jsonb_typeof(identity_map) = 'array'::text) AND ((jsonb_array_length(identity_map) >= 1) AND (jsonb_array_length(identity_map) <= 250)))),
    CONSTRAINT zone_publications_operation_check CHECK ((operation = ANY (ARRAY['draft_publish'::text, 'package_import'::text]))),
    CONSTRAINT zone_publications_request_check CHECK ((jsonb_typeof(request) = 'object'::text)),
    CONSTRAINT zone_publications_request_hash_check CHECK ((request_hash ~ '^[a-f0-9]{64}$'::text))
);

CREATE TABLE fieldmaps_auth_hooks.blocked_email_domains (
    domain text NOT NULL
);

CREATE TABLE fieldmaps_meta.schema_migrations (
    version text NOT NULL,
    applied_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

CREATE FUNCTION fieldmaps_private.zone_authoring_available(p_project uuid,p_site uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE base fieldmaps.site_packages;
BEGIN
 PERFORM fieldmaps_private.assert_active_user();
 IF NOT fieldmaps_private.has_project_role(p_project,ARRAY['manager']) THEN RETURN false; END IF;
 SELECT * INTO base FROM fieldmaps.site_packages WHERE project_id=p_project AND site_id=p_site
   AND id=fieldmaps_private.zone_current_package(p_site) AND state='ready';
 RETURN FOUND AND base.site_boundary IS NOT NULL
   AND EXISTS(SELECT FROM fieldmaps.form_versions WHERE id=base.form_version_id AND state='published')
   AND (base.inventory_form_version_id IS NULL OR EXISTS
     (SELECT FROM fieldmaps.form_versions WHERE id=base.inventory_form_version_id AND state='published'));
END;
$$;
REVOKE ALL ON FUNCTION fieldmaps_private.zone_authoring_available(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fieldmaps_private.zone_authoring_available(uuid,uuid) TO fieldmaps_api;

CREATE VIEW gis.recorded_observations WITH (security_invoker=true,security_barrier=true) AS
SELECT o.qgis_id AS fid,o.id AS observation_id,o.organization_id,o.project_id,o.site_id,s.code AS site_code,
 s.name AS site_name,o.form_version_id,f.code AS form_version,o.created_by AS user_id,o.observer_code,
 o.observed_at,o.received_at,o.revision,o.answers,o.round_type,o.first_round,o.placement_source,
 o.package_id,p.version AS package_version,o.zone_id,zi.code AS zone_code,z.label AS zone_label_at_capture,
 CASE WHEN o.round_type='inventory' THEN 'zone' ELSE 'point' END AS spatial_support,
 o.package_id::text||':'||o.zone_id::text AS snapshot_key,
 CASE WHEN o.round_type='inventory' THEN extensions.ST_AsGeoJSON(z.display_anchor,17)::jsonb END AS display_anchor
FROM fieldmaps.observations o
JOIN fieldmaps.sites s ON (s.organization_id,s.project_id,s.id)=(o.organization_id,o.project_id,o.site_id)
JOIN fieldmaps.form_versions f ON (f.organization_id,f.project_id,f.id)=(o.organization_id,o.project_id,o.form_version_id)
JOIN fieldmaps.site_packages p ON (p.organization_id,p.project_id,p.site_id,p.id)=(o.organization_id,o.project_id,o.site_id,o.package_id)
JOIN fieldmaps.package_zones z ON (z.organization_id,z.project_id,z.site_id,z.package_id,z.zone_id)=(o.organization_id,o.project_id,o.site_id,o.package_id,o.zone_id)
JOIN fieldmaps.zone_identities zi ON (zi.organization_id,zi.project_id,zi.site_id,zi.id)=(z.organization_id,z.project_id,z.site_id,z.zone_id)
WHERE o.deleted_at IS NULL;

CREATE VIEW gis.point_events WITH (security_invoker=true,security_barrier=true) AS
SELECT r.*,extensions.ST_X(o.geom) AS longitude,extensions.ST_Y(o.geom) AS latitude,o.geom
FROM gis.recorded_observations r JOIN fieldmaps.observations o ON o.id=r.observation_id
WHERE r.spatial_support='point';

CREATE VIEW gis.inventory_records WITH (security_invoker=true,security_barrier=true) AS
SELECT r.*,z.geom
FROM gis.recorded_observations r
JOIN fieldmaps.package_zones z ON (z.organization_id,z.project_id,z.site_id,z.package_id,z.zone_id)=
 (r.organization_id,r.project_id,r.site_id,r.package_id,r.zone_id)
WHERE r.spatial_support='zone';

-- Package readers receive immutable publication display metadata without access
-- to the manager-only request, identity mapping, or detailed publication audit.
CREATE FUNCTION fieldmaps_private.zone_package_metadata(p_package uuid)
RETURNS TABLE(published_by uuid,source text,change_note text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT e.created_by,CASE WHEN e.operation='package_import' THEN 'upload' ELSE 'draft' END,e.change_note
 FROM fieldmaps.zone_publications e JOIN fieldmaps.site_packages p ON p.id=e.published_package_id
 WHERE p.id=p_package AND p.state='ready' AND fieldmaps_private.can_read_zone_package(p.id);
$$;
REVOKE ALL ON FUNCTION fieldmaps_private.zone_package_metadata(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fieldmaps_private.zone_package_metadata(uuid) TO fieldmaps_api;

CREATE VIEW gis.zone_snapshots WITH (security_invoker=true,security_barrier=true) AS
SELECT z.organization_id,z.project_id,
 z.site_id,s.code AS site_code,s.name AS site_name,z.package_id,p.version AS package_version,z.zone_id,
 i.code AS zone_code,z.label AS zone_label_at_capture,z.package_id::text||':'||z.zone_id::text AS snapshot_key,
 z.geom,z.display_anchor,z.geometry_sha256,extensions.ST_Area(z.geom::extensions.geography) AS area_m2,
 p.prepared_at,p.prepared_by,e.published_by,e.source,e.change_note
FROM fieldmaps.package_zones z JOIN fieldmaps.site_packages p ON p.id=z.package_id
JOIN fieldmaps.sites s ON s.id=z.site_id JOIN fieldmaps.zone_identities i ON i.id=z.zone_id
JOIN fieldmaps.projects project ON project.id=z.project_id
CROSS JOIN LATERAL fieldmaps_private.zone_package_metadata(z.package_id) e
WHERE p.state='ready' AND (NOT project.is_training OR EXISTS
 (SELECT FROM fieldmaps.observations o WHERE o.package_id=z.package_id AND o.zone_id=z.zone_id
 AND o.created_by=fieldmaps.request_user_id() AND o.deleted_at IS NULL));

CREATE VIEW gis.sample_observations WITH (security_barrier='true') AS
 SELECT o.qgis_id AS fid,
    o.id AS observation_id,
    s.name AS site_name,
    f.code AS form_version,
    o.observer_code,
    o.observed_at,
    o.received_at,
    o.revision,
    extensions.st_x(o.geom) AS longitude,
    extensions.st_y(o.geom) AS latitude,
        CASE
            WHEN ((jsonb_typeof((o.answers -> 'people'::text)) = 'number'::text) AND ((o.answers ->> 'people'::text) ~ '^[0-9]{1,3}$'::text)) THEN ((o.answers ->> 'people'::text))::integer
            ELSE NULL::integer
        END AS people,
        CASE
            WHEN (jsonb_typeof((o.answers -> 'notes'::text)) = 'string'::text) THEN (o.answers ->> 'notes'::text)
            ELSE NULL::text
        END AS notes,
    o.geom
   FROM ((fieldmaps.observations o
     JOIN fieldmaps.sites s ON (((s.organization_id = o.organization_id) AND (s.project_id = o.project_id) AND (s.id = o.site_id))))
     JOIN fieldmaps.form_versions f ON (((f.organization_id = o.organization_id) AND (f.project_id = o.project_id) AND (f.id = o.form_version_id))))
  WHERE ((o.organization_id = '10000000-0000-4000-8000-000000000001'::uuid) AND (o.project_id = '10000000-0000-4000-8000-000000000002'::uuid) AND (EXISTS ( SELECT
           FROM fieldmaps.projects p
          WHERE ((p.id = o.project_id) AND (NOT p.is_training)))) AND (f.code = 'shell-v1'::text) AND (o.deleted_at IS NULL));

