CREATE POLICY assigned_observation_uploads ON fieldmaps.observations FOR INSERT TO fieldmaps_api WITH CHECK (((created_by = fieldmaps.request_user_id()) AND (upload_hash IS NOT NULL) AND fieldmaps_private.has_project_role(project_id, ARRAY['observer'::text, 'manager'::text])));

CREATE POLICY assigned_observations ON fieldmaps.observations FOR SELECT TO fieldmaps_api USING (((project_id IN ( SELECT fieldmaps_private.my_project_ids() AS my_project_ids)) AND (EXISTS ( SELECT
   FROM fieldmaps.projects p
  WHERE ((p.id = observations.project_id) AND ((NOT p.is_training) OR (observations.created_by = fieldmaps.request_user_id())))))));

CREATE POLICY assigned_organizations ON fieldmaps.organizations FOR SELECT TO fieldmaps_api USING ((id IN ( SELECT fieldmaps_private.my_org_ids() AS my_org_ids)));

CREATE POLICY assigned_package_checks ON fieldmaps.package_checks FOR SELECT TO fieldmaps_api USING ((EXISTS ( SELECT
   FROM fieldmaps.site_packages p
  WHERE ((p.id = package_checks.package_id) AND (p.project_id IN ( SELECT fieldmaps_private.my_project_ids() AS my_project_ids))))));

CREATE POLICY assigned_package_zones ON fieldmaps.package_zones FOR SELECT TO fieldmaps_api USING (((project_id IN ( SELECT fieldmaps_private.my_project_ids() AS my_project_ids)) AND fieldmaps_private.can_read_zone_package(package_id)));

CREATE POLICY assigned_packages ON fieldmaps.site_packages FOR SELECT TO fieldmaps_api USING ((project_id IN ( SELECT fieldmaps_private.my_project_ids() AS my_project_ids)));

CREATE POLICY assigned_projects ON fieldmaps.projects FOR SELECT TO fieldmaps_api USING ((id IN ( SELECT fieldmaps_private.my_project_ids() AS my_project_ids)));

CREATE POLICY assigned_site_zone_state ON fieldmaps.site_zone_state FOR SELECT TO fieldmaps_api USING ((project_id IN ( SELECT fieldmaps_private.my_project_ids() AS my_project_ids)));

CREATE POLICY assigned_sites ON fieldmaps.sites FOR SELECT TO fieldmaps_api USING ((project_id IN ( SELECT fieldmaps_private.my_project_ids() AS my_project_ids)));

CREATE POLICY assigned_zone_identities ON fieldmaps.zone_identities FOR SELECT TO fieldmaps_api USING ((project_id IN ( SELECT fieldmaps_private.my_project_ids() AS my_project_ids)));

