CREATE POLICY manager_invitations ON fieldmaps.invitations FOR SELECT TO fieldmaps_api USING ((fieldmaps_private.has_org_role(organization_id, ARRAY['owner'::text, 'admin'::text]) OR ((project_id IS NOT NULL) AND fieldmaps_private.has_project_role(project_id, ARRAY['manager'::text]))));

