CREATE POLICY manager_organization_update ON fieldmaps.organizations FOR UPDATE TO fieldmaps_api USING (fieldmaps_private.has_org_role(id, ARRAY['owner'::text, 'admin'::text])) WITH CHECK (fieldmaps_private.has_org_role(id, ARRAY['owner'::text, 'admin'::text]));



CREATE POLICY manager_project_update ON fieldmaps.projects FOR UPDATE TO fieldmaps_api USING (fieldmaps_private.has_project_role(id, ARRAY['manager'::text])) WITH CHECK (fieldmaps_private.has_project_role(id, ARRAY['manager'::text]));

CREATE POLICY manager_reads_drafts ON fieldmaps.form_versions FOR SELECT TO fieldmaps_api USING (((state = 'draft'::text) AND fieldmaps_private.has_project_role(project_id, ARRAY['manager'::text])));

CREATE POLICY manager_updates_site ON fieldmaps.sites FOR UPDATE TO fieldmaps_api USING (fieldmaps_private.has_project_role(project_id, ARRAY['manager'::text])) WITH CHECK (fieldmaps_private.has_project_role(project_id, ARRAY['manager'::text]));

CREATE POLICY manager_zone_drafts ON fieldmaps.zone_drafts FOR SELECT TO fieldmaps_api USING (fieldmaps_private.has_project_role(project_id, ARRAY['manager'::text]));

CREATE POLICY manager_zone_publications ON fieldmaps.zone_publications FOR SELECT TO fieldmaps_api USING (fieldmaps_private.has_project_role(project_id, ARRAY['manager'::text]));

