ALTER TABLE fieldmaps.site_packages ADD CONSTRAINT site_packages_zone_metadata CHECK (coalesce(
 manifest->'format'='1'::jsonb AND extensions.ST_IsValid(site_boundary)
 AND NOT extensions.ST_IsEmpty(site_boundary) AND extensions.ST_NDims(site_boundary)=2
 AND extensions.ST_XMin(site_boundary::extensions.box3d)>=-180 AND extensions.ST_XMax(site_boundary::extensions.box3d)<=180
 AND extensions.ST_YMin(site_boundary::extensions.box3d)>=-85 AND extensions.ST_YMax(site_boundary::extensions.box3d)<=85
 AND extensions.ST_XMax(site_boundary::extensions.box3d)-extensions.ST_XMin(site_boundary::extensions.box3d)<=1
 AND extensions.ST_YMax(site_boundary::extensions.box3d)-extensions.ST_YMin(site_boundary::extensions.box3d)<=1,false));
-- Dashboard-created event trigger; browser API roles never need to invoke it.
-- Event-trigger execution itself does not require these client EXECUTE grants.
-- Projects created without the dashboard's automatic-RLS option have no such function.
DO $$
BEGIN
  IF to_regprocedure('public.rls_auto_enable()') IS NOT NULL THEN
    REVOKE EXECUTE ON FUNCTION public.rls_auto_enable() FROM PUBLIC, anon, authenticated, service_role;
  END IF;
END;
$$;
CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;
REVOKE ALL ON SCHEMA cron FROM PUBLIC, anon, authenticated, service_role, fieldmaps_api;

SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'fieldmaps_training_purge';
SELECT cron.schedule('fieldmaps_training_purge', '17 3 * * *', $purge$
  DELETE FROM fieldmaps.observations
  WHERE project_id = '10000000-0000-4000-8000-000000000102'
    AND received_at < now() - interval '30 days';
$purge$);

SET check_function_bodies=true;
